comms.text:
@1 חֲזֵי דִי אֲנָא יָהֵב קֳדָמֵיכוֹן יוֹמָא דֵין בִּרְכָן וּלְוָטִין:
@2 יָת בִּרְכָן דִי תְקַבְּלוּן לְפִקוּדַיָא דַיְיָ אֳלָהֲכוֹן דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין:
@3 וּלְוָטִין אִם לָא תְקַבְּלוּן לְפִקוּדַיָא דַיְיָ אֱלָהֲכוֹן וְתִסְטוּן מִן אָרְחָא דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין לִמְהַךְ בָּתַר טַעֲוַת עַמְמַיָא דִי לָא יְדַעְתּוּן:
@4 וִיהֵי אֲרֵי יָעֵלִנָךְ יְיָ אֱלָהָךְ לְאַרְעָא דִי אַתְּ עָלֵל תַּמָן לְמֵירְתַהּ וְתִתֵּן יָת מְבָרְכַיָא עַל טוּרָא דִגְרִזִין וְיָת מְלַטְטַיָא עַל טוּרָא דְעֵיבָל:
@5 הֲלָא אִנוּן בְּעִבְרָא דְיַרְדְנָא אֲחוֹרֵי אֹרַח מַעֲלָנֵי שִׁמְשָׁא בְּאַרְעָא כְּנַעְנָאָה דְיָתֵב בְּמֵישְׁרָא לָקֳבֵל גִלְגְלָא בִּסְטַר מֵישְׁרֵי מֹרֶה:
@6 אֲרֵי אַתּוּן עָבְרִין יָת יַרְדְנָא לְמֵעַל לְמֵירַת יָת אַרְעָא דַיְיָ אֱלָהֲכוֹן יָהֵב לְכוֹן וְתֵירְתוּן יָתַהּ וְתֵיתְבוּן בַּהּ:
@7 וְתִטְרוּן לְמֶעְבַּד יָת כָּל קְיָמַיָא וְיָת דִינַיָא דִי אֲנָא יָהֵב קֳדָמֵיכוֹן יוֹמָא דֵין:
@8 אִלֵין קְיָמַיָא וְדִינַיָא דִי תִטְרוּן לְמֶעְבַּד בְּאַרְעָא דִיהַב יְיָ אֱלָהָא דַאֲבְהָתָךְ לָךְ לְמֵירְתַהּ כָּל יוֹמַיָא דִי אַתּוּן קַיָמִין עַל אַרְעָא:
@9 אַבָּדָא תְאַבְּדוּן יָת כָּל אַתְרַיָא דִי פְלָחוּ תַמָן עַמְמַיָא דִי אַתּוּן יָרְתִין יָתְהוֹן יָת טַעֲוָתְהוֹן עַל טוּרַיָא רָמַיָא וְעַל רָמָתָא וּתְחוֹת כָּל אִילַן עַבּוֹף:
@10 וּתְתָרְעוּן יָת אֱגוֹרֵיהוֹן וּתְתַבְּרוּן יָת קָמָתְהוֹן וַאֲשֵׁרֵיהוֹן תּוֹקְדוּן בְּנוּרָא וְצַלְמֵי טַעֲוָתְהוֹן תְּקוֹצְצוּן וְתוֹבְדוּן יָת שִׁמְהוֹן מִן אַ:תרָא הַהוּא:
@11 לָא תַעְבְּדוּן כֵּן קֳדָם יְיָ אֱלָהָכוֹן:
@12 אֱלָהֵן לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהֲכוֹן מִכָּל שִׁבְטֵּיכוֹן לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן לְבֵית שְׁכִנְתֵּהּ תִּתְבְּעוּן וְתֵיתוּן לְתַמָן:
@13 וְתַיְתוּן לְתַמָן עֲלָוָתֵיכוֹן וְנִכְסַת קוּדְשֵׁיכוֹן וְיָת מַעְשְׂרָתֵיכוֹן וְיָת אַפְרָשׁוּת יֶדְכוֹן וְנִדְרֵיכוֹן וְנִדְבָתֵיכוֹן וּבְכוֹרֵי תוֹרְכוֹן וְעָנְכוֹן:
@14 וְתֵיכְלוּן תַּמָן קֳדָם יְיָ אֱלָהֲכוֹן וְתֶחֱדוּן בְכֹל אוֹשָׁטוּת יֶדְכוֹן אַתּוּן וֶאֱנַשׁ בָּתֵּיכוֹן דִי בָרְכָךְ יְיָ אֱלָהָךְ:
@15 לָא תַעְבְּדוּן כְּכֹל דִי אֲנַחְנָא עָבְדִין הָכָא יוֹמָא דֵין גְבַר כָּל מָן דְכָשַׁר קֳדָמוֹהִי:
@16 אֲרֵי לָא אֲתֵיתוּן עַד כְּעָן לְבֵית נְיָחָא וּלְאַחֲסָנָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@17 וְתַעְבְּרוּן יָת יַרְדְנָא וְתֵיתְבוּן בְּאַרְעָא דַיְיָ אֱלָהֲכוֹן מַחְסֵן יָתְכוֹן וִינִיחַ לְכוֹן מִכָּל בַּעֲלֵי דְבָבֵיכוֹן מִסְחוֹר סְחוֹר וְתֵיתְבוּן לְרָחְצָן:
@18 וִיהֵי אַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהֲכוֹן בֵּהּ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן לְתַמָן תַּיְתוּן יָת כָּל דִי אֲנָא מְפַקֵד יָתְכוֹן עֲלָוָתֵיכוֹן וְנִכְסַת קוּדְשֵׁיכוֹן מַעְשְׂרָתֵיכוֹן וְאַפְרָשׁוּת יֶדְכוֹן וְכֹל שְׁפַר נִדְרֵיכוֹן דִי תִדְרוּן קֳדָם יְיָ:
@19 וְתֶחֱדוּן קֳדָם יְיָ אֱלָהֲכוֹן אַתּוּן וּבְנֵיכוֹן וּבְנָתֵיכוֹן וְעַבְדֵיכוֹן וְאַמְהָתֵיכוֹן וְלֵוָאָה דִי בְקִרְוֵיכוֹן אֲרֵי לֵית לֵהּ חֳלָק וְאַחֲסָנָא עִמְכוֹן:
@20 אִסְתַּמַר לָךְ דִילְמָא תַסֵק עֲלָוָתָךְ בְּכָל אַתְרָא דִי תֶחֱזֵי:
@21 אֶלָהֵן בְּאַתְרָא דִי יִתִּרְעֵי יְיָ בְּחַד מִן שִׁבְטָיךְ תַּמָן תַּסֵק עֲלָוָתָךְ וְתַמָן תַּעְבֵּד כֹּל דִי אֲנָא מְפַקְדָךְ:
@22 לְחוֹד בְּכָל רְעוּת נַפְשָׁךְ תִּכּוֹס וְתֵיכוּל בִּשְׂרָא כְּבִרְכְּתָא דַיְיָ אֱלָהָךְ דִי יְהַב לָךְ בְּכָל קִרְוָיךְ מְסָאָבָא וְדַכְיָא יֵכְלֻנֵהּ כִּבְשַׂר טַבְיָא וְאַיְלָא:
@23 לְחוֹד דְמָא לָא תֵיכְלוּן עַל אַרְעָא תִשְׁדִנֵהּ כְּמַיָא:
@24 לֵית לָךְ רְשׁוּ לְמֵיכַל בְּקִרְוָיךְ מַעְשַׂר עִבוּרָךְ חַמְרָךְ וּמִשְׁחָךְ וּבְכוֹרֵי תוֹרָךְ וְעָנָךְ וְכָל נִדְרָךְ דִי תִדַר וְנִדְבָתָיךְ וְאַפְרָשׁוּת יְדָךְ:
@25 אֱלָהֵן קֳדָם יְיָ אֱלָהָךְ תֵּיכְלִנֵהּ בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ אַתְּ וּבְרָךְ וּבְרַתָּךְ וְעַבְדָךְ וְאַמְתָךְ וְלֵוָאָה דִי בְקִרְוָיךְ וְתֶחֱדֵי קֳדָם יְיָ אֱלָהָךְ בְּכָל אוֹשָׁטּוּת יְדָךְ:
@26 אִסְתַּמַר לָךְ דִילְמָא תִשְׁבּוֹק יָת לֵוָאֵי כָּל יוֹמָיךְ עַל אַרְעָךְ:
@27 אֲרֵי יַפְתֵּי יְיָ אֱלָהָךְ יָת תְּחוּמָךְ כְּמָא דִי מַלִיל לָךְ וְתֵימַר אֵיכוּל בִּשְׂרָא אֲרֵי תִתִּרְעֵי נַפְשָׁךְ לְמֵיכַל בִּשְׂרָא בְּכָל רְעוּת נַפְשָׁךְ תֵּיכוּל בִּשְׂרָא:
@28 אֲרֵי יִתְרָחַק מִנָךְ אַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן וְתִכּוֹס מִתּוֹרָךְ וּמֵעָנָךְ דִי יְהַב יְיָ לָךְ כְּמָא דִי פַּקֵדִתָּךְ וְתֵיכוּל בְּקִרְוָיךְ בְּכֹל רְעוּת נַפְשָׁךְ:
@29 בְּרַם כְּמָא דִי מִתְאֲכֵל בְּשַׂר טַבְיָא וְאַיְלָא כֵּן תֵּיכְלִנֵהּ מְסָאָבָא וְדַכְיָא כַּחֲדָא יֵכְלִנֵהּ:
@30 לְחוֹד תְּקֵף בְּדִיל דְלָא לְמֵיכַל דְּמָא אֲרֵי דְמָא הוּא נַפְשָׁא וְלָא תֵיכוּל נַפְשָׁא עִם בִּשְׂרָא:
@31 לָא תֵּיכְלִנֵהּ עַל אַרְעָא תִשְׁדִנֵהּ כְּמַיָא:
@32 לָא תֵּיכְלִנֵהּ בְּדִיל דְיֵיטַב לָךְ וְלִבְנָיךְ בַּתְרָךְ אֲרֵי תַעְבֵּד דְכָשָׁר קֳדָם יְיָ:
@33 לְחוֹד מַעְשַׂר קוּדְשָׁיךְ דִיהוֹן לָךְ וְנִדְרָךְ תִּטוֹל וְתֵיתֵי לְאַתְרָא דִי יִתִּרְעֵי יְיָ:
@34 וְתַעְבֵּד עֲלָוָתָךְ בִּשְׂרָא וּדְמָא עַל מַדְבְּחָא דַיְיָ אֱלָהָךְ וְדַם נִכְסַת קוּדְשָׁיךְ יִתָּשַׁד עַל מַדְבְּחָא דַיְיָ אֱלָהָךְ וּבִשְׂרָא תֵּיכוּל:
@35 טַר וּתְקַבֵּל יָת כָּל פִּתְגָמַיָא הָאִלֵין דִי אֲנָא מְפַקְדָךְ בְּדִיל דְיֵיטַב לָךְ וְלִבְנָיךְ בַּתְרָךְ עַד עֳלָם אֲרֵי תַעְבֵּד דְתָקֵן וּדְכָשַׁר קֳדָם יְיָ אֱלָהָךְ:
@36 אֲרֵי יְשֵׁצֵי יְיָ אֱלָהָךְ יָת עַמְמַיָא דִי אַתְּ עָלֵל לְתַמָן לְתָרָכָא יָתְהוֹן מִקֳדָמָךְ וְתֵירַת יָתְהוֹן וְתֵיתַב בְּאַרְעֲהוֹן:
@37 אִסְתַּמַר לָךְ דִילְמָא תִתָּקַל בַּתְרֵיהוֹן בָּתַר דְיִשְׁתֵּצוּן מִקֳדָמָךְ וְדִילְמָא תִתְבַּע לְטַעֲוָתְהוֹן לְמֵימַר אֶכְדֵין פָּלְחִין עַמְמַיָא הָאִלֵין יָת טַעֲוָתְהוֹן וְאֶעְבֵּד כֵּן אַף אֲנָא:
@38 לָא תַעְבֵּד כֵּן קֳדָם יְיָ אֱלָהָךְ אֲרֵי כָּל דִמְרָחָק קֳדָם יְיָ דִי סָנֵי עֲבָדוּ לְטַעֲוָתְהוֹן אֲרֵי אַף יָת בְּנֵיהוֹן וְיָת בְּנָתֵיהוֹן מוֹקְדִין בְּנוּרָא לְטַּעֲוָתְהוֹן:
@39 יָת כָּל פִּתְגָמָא דִי אֲנָא מְפַקֵד יָתְכוֹן יָתֵהּ תִּטְרוּן לְמֶעְבָּד לָא תוֹסְפוּן עֲלוֹהִי וְלָא תִמְנְעוּן מִנֵהּ:
@40 אֲרֵי יְקוּם בֵּינָךְ נְבִיָא אוֹ חָלֵם חֶלְמָא וְיִתֶּן לָךְ אָת אוֹ מוֹפְתָא:
@41 וְיֵיתֵי אָתָא וּמוֹפְתָא דִי מַלִיל עִמָךְ לְמֵימָר נְהַךְ בָּתַר טַעֲוַת עַמְמַיָא דִי לָא יְדַעְתָּנוּן וְנִפְלְחִנוּן:
@42 לָא תְקַבֵּל לְפִתְגָמֵי נְבִיָא הַהוּא אוֹ לְחָלֵם חֶלְמָא הַהוּא אֲרֵי מְנַסֵי יְיָ אֱלָהֲכוֹן יָתְכוֹן לְמִדַע הַאִיתֵיכוֹן רָחֲמִין יָת יְיָ אֱלָהֲכוֹן בְכָל לִבְּכוֹן וּבְכָל נַפְשְׁכוֹן:
@43 בָּתַר דַחַלְתָּא דַיְיָ אֱלָהֲכוֹן תְהָכוּן וְיָתֵהּ תִּדְחֲלוּן וְיָת פִּקוּדוֹהִי תִטְּרוּן וּלְמֵימְרֵהּ תְּקַבְּלוּן וְקָדָמוֹהִי תִפְלְחוּן וּבְדַחַלְתֵּהּ תִּתְקָרְבוּן:
@44 וּנְבִיָא הַהוּא אוֹ חָלֵם חֶלְמָא הַהוּא יִתְקְטֵּל אֲרֵי מַלִיל סַטְיָא עַל יְיָ אֱלָהֲכוֹן דִי אַפֵּיק יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם וּדְפָרְקָךְ מִבֵּית עַבְדוּתָא לְאַטְעֲיוּתָךְ מִן אָרְחָא דִי פַקְדָךְ יְיָ אֱלָהָךְ לִמְהַךְ בַּהּ וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@45 אֲרֵי יְמַלְכִנָךְ אֲחוּךְ בַּר אִמָךְ אוֹ בְרָךְ אוֹ בְרַתָּךְ אוֹ אִתַּת קְיָמָךְ אוֹ חַבְרָךְ דִי כְנַפְשָׁךְ בְּסִתְרָא לְמֵימַר נְהַךְ וְנִפְלַח לְטַעֲוַת עַמְמַיָא דִי לָא יְדַעְתְּ אַתְּ וַאֲבָהָתָךְ:
@46 מִטַעֲוַת עַמְמַיָא דִי בְסַחֲרָנֵיכוֹן דִקְרִיבִין לָךְ אוֹ דִרְחִיקִין מִנָךְ מִסְיָפֵי אַרְעָא וְעַד סְיָפֵי אַרְעָא:
@47 לָא תֵיבֵי לֵהּ וְלָא תְקַבֵּל מִנֵהּ וְלָא תְחוּס עֵינָךְ עֲלוֹהִי וְלָא תְרַחַם וְלָא תְכַסֵי עֲלוֹהִי:
@48 אֲרֵי מִקְטַל תִּקְטְּלִנֵהּ יְדָךְ תְּהֵי בֵהּ בְּקַדְמֵיתָא לְמִקְטְלֵהּ וִידָא דְכָל עַמָא בְבַתְרֵיתָא:
@49 וְתִרְגְמִנֵהּ בְּאַבְנַיָא וִימוּת אֲרֵי בָעָא לְאַטְעֲיוּתָךְ מִדַחַלְתָּא דַיְיָ אֱלָהָךְ דִי אַפְּקָךְ מֵאַרְעָא דְמִצְרַיִם מִבֵּית עַבְדוּתָא:
@50 וְכָל יִשְׂרָאֵל יִשְׁמְעוּן וְיִדְחֲלוּן וְלָא יוֹסְפוּן לְמֶעְבַּד כְּפִתְגָמָא בִישָׁא הָדֵין בֵּינָךְ:
@51 אֲרֵי תִשְׁמַע בְּחַד מִקִרְוָיךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְמִתַּב תַּמָן לְמֵימָר:
@52 נְפָקוּ גֻבְרִין בְּנֵי רִשְׁעָא מִבֵּינָךְ וְאַטְעָיוּ יָת יָתְבֵי קַרְתְּהוֹן לְמֵימָר נְהַךְ וְנִפְלַח לְטַעֲוַת עַמְמַיָא דִי לָא יְדַעְתּוּן:
@53 וְתִתְבַּע וְתִבְדוֹק וְתִשְׁאַל יָאוּת וְהָא קֻשְׁטָּא כֵּוַן פִּתְגָמָא אִתְעֲבִידָא תּוֹעֶבְתָּא הָדָא בֵּינָךְ:
@54 מִמְחָא תִמְחֵי יָת יָתְבֵי קַרְתָּא הַהִיא לְפִתְגַם דְחָרֶב גַמַר יָתַהּ וְיָת כָּל דִי בַהּ וְיָת בְּעִירַהּ לְפִתְגַם דְחָרֶב:
@55 וְיָת כָּל עֲדָאַהּ תִּכְנוֹשׁ לְגוֹ פְתָיַהּ וְתוֹקֵד בְּנוּרָא יָת קַרְתָּא וְיָת כָּל עֲדָאַהּ גְמִיר קֳדָם יְיָ אֱלָהָךְ וּתְהֵי תֵּל חָרִיב לְעָלָם לָא תִתְבְּנֵי עוֹד:
@56 וְלָא יִדְבַּק בִּידָךְ מִדַעַם מִן חֶרְמָא בְּדִיל דִיתוּב יְיָ מִתְּקוֹף רוּגְזֵהּ וִיהַב לָךְ רַחֲמִין וִירַחַם עֲלָךְ וְיַסְגִנָךְ כְּמָא דִי קַיִים לַאֲבָהָתָךְ:
@57 אֲרֵי תְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר יָת כָּל פִּקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמֶעְבַּד דְכָשָׁר קֳדָם יְיָ אֱלָהָךְ:
@58 בְּנִין אַתּוּן קֳדָם יְיָ אֱלָהֲכוֹן לָא תִתְחַמְמוּן וְלָא תְשַׁווּן מְרָט בֵּין עֵינֵיכוֹן עַל מִית:
@59 אֲרֵי עַם קַדִישׁ אַתְּ קֳדָם יְיָ אֱלָהָךְ וּבָךְ אִתִּרְעֵי יְיָ לְמֶהֱוֵי לֵהּ לְעַם חַבִּיב מִכָּל עַמְמַיָא דִי עַל אַפֵּי אַרְעָא:
@60 לָא תֵיכוּל כָּל דִמְרָחָק:
@61 דֵין בְּעִירָא דְתֵיכְלוּן תּוֹרִין אִמְרִין דִרְחֵלִין וְגָדְיָן דְעִזִין:
@62 אַיָלָא וְטַבְיָא וְיַחְמוּרָא וְיַעְלָא וְרֵימָא וְתוֹרְבָּלָא וְדִיצָא:
@63 וְכָל בְּעִירָא דִסְדִיקָא פַרְסָתָא וּמַטִלְפָא טִלְפִין תַּרְתֵּין פַּרְסָתָא מַסְקָא פִשְׁרָא בִּבְעִירָא יָתַהּ תֵּיכְלוּן:
@64 בְּרַם יָת דֵין לָא תֵיכְלוּן מִמַסְקֵי פִשְׁרָא וּמִמַסְדִיקֵי פַרְסָתָא מַטִלְפֵי טִלְפַיָא יָת גַמְלָא וְיָת אַרְנְבָא וְיָת טַּפְזָא אֲרֵי מַסְקֵי פִּשְׁרָא אִנוּן וּפַרְסָתְהוֹן לָא סְדִיקָא מְסָאֲבִין אִנוּן לְכוֹן:
@65 וְיָת חֲזִירָא אֲרֵי מַסְדִיק פַּרְסָתָא הוּא וְלָא פָשַׁר מְסָאָב הוּא לְכוֹן מִבִּסְרְהוֹן לָא תֵיכְלוּן וּבִנְבֵלְתְּהוֹן לָא תִקְרְבוּן:
@66 יָת דֵין תֵּיכְלוּן מִכֹּל דִי בְמַיָא כֹּל דִי לֵהּ צִיצִין וְקַלְפִין תֵּיכְלוּן:
@67 וְכֹל דִי לֵית לֵהּ צִיצִין וְקַלְפִין לָא תֵיכְלוּן מְסָאָב הוּא לְכוֹן:
@68 כָּל צִפַּר דַכְיָא תֵּיכְלוּן:
@69 וְדֵין דִי לָא תֵיכְלוּן מִנְהוֹן נִשְׁרָא וְעָר וְעַזְיָא:
@70 וּבַת כַּנְפָא וְטָרָפִיתָא וְדַיְתָא לִזְנַהּ:
@71 וְיָת כָּל עֹרְבָא לִזְנֵהּ:
@72 וְיָת בַּת נַעֲמִיתָא וְצִיצָא וְצִפַּר שַׁחְפָּא וְנָצָא לִזְנוֹהִי:
@73 וְקַדְיָא וְקִפוֹפָא וּבַוְתָא:
@74 וְקָתָא וִירַקְרֵקָא וְשָׁלֵי נוּנָא:
@75 וְחַוָרִיתָא וְאִבּוּ לִזְנַהּ וְנַגַר טוּרָא וַעֲטַּלֵפָא:
@76 וְכֹל רִחֲשָׁא דְעוֹפָא מְסָאָב הוּא לְכוֹן לָא יִתְאָכְלוּן:
@77 כָּל עוֹפָא דְכֵי תֵּיכְלוּן:
@78 לָא תֵיכְלוּן כָּל נְבִילָא לְתוֹתָב עָרֵל דִי בְקִרְוָיךְ תִּתְּנִנַהּ וְיֵיכְלִנַהּ אוֹ תְזַבְּנִנַהּ לְבַר עַמְמִין אֲרֵי עַם קַדִישׁ אַתְּ קֳדָם יְיָ אֱלָהָךְ לָא תֵיכוּל בְּשַׂר בַּחֲלָב:
@79 עַשְׂרָא תְעַשַׂר יָת כָּל עֲלָלַת זַרְעָךְ דְיִפּוֹק חַקְלָא שַׁתָּא בְשַׁתָּא:
@80 וְתֵיכוּל קֳדָם יְיָ אֱלָהָךְ בְּאַתְרָא דִי יִתִּרְעֵי לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן מַעְשַׂר עִבוּרָךְ חַמְרָךְ וּמִשְׁחָךְ וּבְכוֹרֵי תוֹרָךְ וְעָנָךְ בְּדִיל דְתֵילַף לְמִדְחַל קֳדָם יְיָ אֱלָהָךְ כָּל יוֹמַיָא:
@81 וַאֲרֵי יִסְגֵי מִנָךְ אָרְחָא אֲרֵי לָא תִכּוּל לְמִטְלֵהּ אֲרֵי יִתְרָחַק מִנָךְ אַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן אֲרֵי יְבָרֵכִנָךְ יְיָ אֱלָהָךְ:
@82 וְתִתֵּן בְּכַסְפָּא וּתְצוּר כַּסְפָּא בִּידָךְ וּתְהַךְ לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ:
@83 וְתִתֵּן כַּסְפָּא בְּכֹל דִי יִתִּרְעֵי נַפְשָׁךְ בְּתוֹרֵי וּבְעָנָא וּבַחֲמַר חֲדַת וְעַתִּיק וּבְכֹל דִי תִשְׁאֲלִנָךְ נַפְשָׁךְ וְתֵיכוּל תַּמָן קֳדָם יְיָ אֱלָהָךְ וְתֶחֱדֵי אַתְּ וֶאֱנַשׁ בֵּיתָךְ:
@84 וְלֵוָאָה דִי בְקִרְוָיךְ לָא תִשְׁבְּקִנֵהּ אֲרֵי לֵית לֵהּ חֳלָק וְאַחֲסָנָא עִמָךְ:
@85 מִסוֹף תְּלַת שְׁנִין תַּפֵק יָת כָּל מַעְשַׂר עֲלַלְתָּךְ בְּשַׁתָּא הַהִיא וְתַצְנַע בְּקִרְוָיךְ:
@86 וְיֵיתֵי לֵוָאָה אֲרֵי לֵית לֵהּ חֳלָק וְאַחֲסָנָא עִמָךְ וְגִיוֹרָא וְיִתַּמָא וְאַרְמְלָא דִי בְקִרְוָיךְ וְיֵיכְלוּן וְיִשְׂבְּעוּן בְּדִיל דִי יְבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכָל עוֹבָדֵי יְדָךְ דִי תַעְבֵּד:
@87 מִסוֹף שְׁבַע שְׁנִין תַּעְבֵּד שְׁמִטְתָא:
@88 וְדֵין פִּתְגַם שְׁמִטְתָא דְתַשְׁמֵט כָּל גְבַר מַרֵי רְשׁוּ דִי יַרְשֵׁי בְּחַבְרֵהּ לָא יִתְבַּע מִן חַבְרֵהּ וּמִן אֲחוּהִי אֲרֵי קְרָא שְׁמִטְתָא קֳדָם יְיָ:
@89 מִן בַּר עַמְמִין תִּתְבַּע וְדִי יְהֵי לָךְ עִם אָחוּךְ תַּשְׁמֵט יְדָךְ:
@90 לְחוֹד אֲרֵי לָא יְהֵי בָךְ מִסְכֵּנָא אֲרֵי בָרָכָא יְבָרֵכִנָךְ יְיָ בְּאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא לְמֵירְתַהּ:
@91 לְחוֹד אִם קַבָּלָא תְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר לְמֶעְבַּד יָת כָּל תַּפְקֶדְתָּא הָדָא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין:
@92 אֲרֵי יְיָ אֱלָהָךְ בָּרְכָךְ כְּמָא דִי מַלִיל לָךְ וְתוֹזֵף לְעַמְמִין סַגִיאִין וְאַתְּ לָא תְזוּף וְתִשְׁלוֹט בְּעַמְמִין סַגִיאִין וּבָךְ לָא יִשְׁלְטוּן:
@93 אֲרֵי יְהֵי בָךְ מִסְכֵּנָא מֵחַד מֵאַחָיךְ בַּחֲדָא מִקִרְוָיךְ בְּאַרְעָךְ דַיְיָ אֱלָהָךְ יָהֵב לָךְ לָא תַתְקֵף יָת לִבָּךְ וְלָא תִקְפֹּץ יָת יְדָךְ מֵאֲחוּךְ מִסְכֵּנָא:
@94 אֶלָא מִפְתַּח תִּפְתַּח יָת יְדָךְ לֵהּ וְאוֹזָפָא תּוֹזְפִנֵהּ כְּמִסַת חֶסְרוֹנֵהּ דְיַחֲסִיר לֵהּ:
@95 אִסְתַּמַר לָךְ דִילְמָא יְהֵי פִתְגָם עִם לִבָּךְ בִּרְשַׁע לְמֵימַר קְרִיבָא שַׁתָּא שְׁבִיעֲתָא שַׁתָּא דִשְׁמִטְתָא וְתַבְאֵשׁ עֵינָךְ בְּאָחוּךְ מִסְכֵּנָא וְלָא תִתֵּן לֵהּ וְיִקְרֵי עֲלָךְ קֳדָם יְיָ וִיהֵי בָךְ חוֹבָא:
@96 מִתַּן תִתֵּן לֵהּ וְלָא יַבְאֵשׁ לִבָּךְ בְּמִתְּנָךְ לֵהּ אֲרֵי בְּדִיל פִּתְגָמָא הָדֵין יְבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכָל עוֹבָדָךְ וּבְכֹל אוֹשָׁטוּת יְדָךְ:
@97 אֲרֵי לָא יִפְסוֹק מִסְכֵּנָא מִגוֹ אַרְעָא עַל כֵּן אֲנָא מְפַקְדָךְ לְמֵימַר מִפְתַּח תִּפְתַּח יָת יְדָךְ לַאֲחוּךְ לְעַנְיָךְ וּלְמִסְכֵּנָךְ בְּאַרְעָךְ:
@98 אֲרֵי יִזְדַבַּן לָךְ אֲחוּךְ בַּר יִשְׂרָאֵל אוֹ בַּת יִשְׂרָאֵל וְיִפְלְחִנָךְ שִׁית שְׁנִין וּבְשַׁתָּא שְׁבִיעֲתָא תִּפְטְרִנֵהּ בַּר חוֹרִין מֵעִמָךְ:
@99 וַאֲרֵי תִפְטְרִנֵה בַּר חוֹרִין מֵעִמָךְ לָא תִפְטְּרִנֵה רֵיקָן:
@100 אַפְרָשָׁא תַפְרֵשׁ לֵהּ מֵעָנָךְ וּמֵאִדְרָךְ וּמִמַעֲצַרְתָּךְ דִי בָרְכָךְ יְיָ אֱלָהָךְ תִּתֶּן לֵהּ:
@101 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּאַרְעָא דְמִצְרַיִם וּפָרְקָךְ יְיָ אֱלָהָךְ עַל כֵּן אֲנָא מְפַקְדָךְ יָת פִּתְגָמָא הָדֵין יוֹמָא דֵין:
@102 וִיהֵי אֲרֵי יֵימַר לָךְ לָא אֶפוֹק מֵעִמָךְ אֲרֵי רָחֲמָךְ וְיָת אֱנַשׁ בֵּיתָךְ אֲרֵי טַב לֵהּ עִמָךְ:
@103 וְתִסַב יָת מַרְצְעָא וְתִתֵּן בְּאֻדְנֵהּ וּבְדָשָׁא וִיהֵי לָךְ עִבֵד פָּלַח לְעָלָם וְאַף לְאַמְתָךְ תַּעְבֶּד כֵּן:
@104 לָא יִקְשֵׁי בְעֵינָךְ בְּמִפְטְרָךְ יָתֵהּ בַּר חוֹרִין מֵעִמָךְ אֲרֵי עַל חַד תְּרֵין כַּאֲגַר אֲגִירָא פָּלְחָךְ שִׁית שְׁנִין וִיבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכֹל דִי תַעְבֵּד:
@105 כָּל בּוּכְרָא דִי יִתְיְלִיד בְּתוֹרָךְ וּבְעָנָךְ דִכְרִין תַּקְדֵשׁ קָדָם יְיָ אֱלָהָךְ לָא תִפְלַח בְּבוּכְרָא דְתוֹרָךְ וְלָא תֵגוֹז בּוּכְרָא דְעָנָךְ:
@106 קֳדָם יְיָ אֱלָהָךְ תֵּיכְלִנֵהּ שַׁתָּא בְשַׁתָּא בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אַתְּ וֶאֱנַשׁ בֵּיתָךְ:
@107 וַאֲרֵי יְהֵי בֵהּ מוּמָא חֲגִיר אוֹ עֲוִיר כֹּל מוּם בִּישׁ לָא תִכְּסִנֵהּ קֳדָם יְיָ אֱלָהָךְ:
@108 בְּקִרְוָיךְ תֵּיכְלִנֵהּ מְסָאָבָא וְדַכְיָא כַּחֲדָא כִּבְסַר טַבְיָא וְאַיְלָא:
@109 לְחוֹד יָת דְמֵהּ לָא תֵיכוּל עַל אַרְעָא תִשְׁדִנֵהּ כְּמַיָא:
@110 טַר יָת יַרְחָא דַאֲבִיבָא וְתַעְבֵּד פִּסְחָא קֳדָם יְיָ אֱלָהָךְ אֲרֵי בְּיַרְחָא דַאֲבִיבָא אַפְּקָךְ יְיָ אֱלָהָךְ מִמִצְרַיִם וַעֲבַד לָךְ נִסִין בְּלֵילְיָא:
@111 וְתִכּוֹס פִּסְחָא קֳדָם יְיָ אֱלָהָךְ מִן בְּנֵי עָנָא וְנִכְסַת קוּדְשַׁיָא מִן תּוֹרֵי בְּאַתְרָא דִי יִתִּרְעֵי יְיָ לְאַשְׁרָאָה שְׁכִנְתֵּה תַּמָן:
@112 לָא תֵיכוּל עֲלוֹהִי חֲמִיעַ שִׁבְעָא יוֹמִין תֵּיכוּל עֲלוֹהִי פַטִיר לְחֵם עֹנִי אֲרֵי בִּבְהִילוּ נְפַקְתָּא מֵאַרְעָא דְמִצְרַיִם בְּדִיל דְתִדְכַּר יָת יוֹמָא מִפְּקָךְ מֵאַרְעָא דְמִצְרַיִם כָּל יוֹמֵי חַיָיךְ:
@113 וְלָא יִתְחֲזֵי לָךְ חֲמִר בְּכָל תְּחוּמָךְ שִׁבְעָא יוֹמִין וְלָא יְבִית מִן בִּסְרָא דִי תִכּוֹס בְּרַמְשָׁא בְּיוֹמָא קַדְמָאָה לְצַפְרָא:
@114 לֵית לָךְ רְשׁוּ לְמִכֹּס יָת פִּסְחָא בַּחֲדָא מִקִרְוָיךְ דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@115 אֱלָהֵן לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן תִּכּוֹס יָת פִּסְחָא בְּרַמְשָׁא כְּמֵעַל שִׁמְשָׁא זְמַן מִפְקָךְ מִמִצְרָיִם:
@116 וּתְבַשֵׁל וְתֵיכוּל בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ וְתִתְפְּנֵי בְצַפְרָא וּתְהַךְ לְקִרְוָיךְ:
@117 שִׁתָּא יוֹמִין תֵּיכוּל פַּטִירָא וּבְיוֹמָא שְׁבִיעָאָה כְּנֵשׁ קֳדָם יְיָ אֱלָהָךְ לָא תַעְבֵּד עִבִידָא:
@118 שִׁבְעָא שָׁבוּעִין תִּמְנֵי לָךְ מִדְשַׁרְיוּת מַגְלָא בַּחֲצַד עוּמְרָא דַאֲרָמוּתָא תִּשְׁרֵי לְמִמְנֵּי שִׁבְעָא שָׁבוּעִין:
@119 וְתַעְבֵּד חַגָא דְשָׁבוּעַיָא קֳדָם יְיָ אֱלָהָךְ מִסַת נִדְבַת יְדָךְ דִי תִתֵּן כְּמָא דִי יְבָרֵכִנָךְ יְיָ אֱלָהָךְ:
@120 וְתֶחֱדֵי קֳדָם יְיָ אֱלָהָךְ אַתְּ וּבְרָךְ וּבְרַתָּךְ וְעַבְדָךְ וְאַמְתָךְ וְלֵוָאָה דִי בְקִרְוָיךְ וְגִיוֹרָא וְיִתַּמָא וְאַרְמְלָא דִי בֵינָךְ בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן:
@121 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּמִצְרָיִם וְתִטַר וְתַעְבֵּד יָת קְיָמַיָא הָאִלֵין:
@122 חַגָא דִמְטָלַיָא תַּעְבֵּד לָךְ שִׁבְעָא יוֹמִין בְּמִכְנְשָׁךְ מֵאִדְרָךְ וּמִמַעְצַרְתָּךְ:
@123 וְתֶחֱדֵי בְּחַגָךְ אַתְּ וּבְרָךְ וּבְרַתָּךְ וְעַבְדָךְ וְאַמְתָךְ וְלֵוָאָה וְגִיוֹרָא וְיִתַּמָא וְאַרְמְלָא דִי בְקִרְוָיךְ:
@124 שִׁבְעָא יוֹמִין תֵּחוֹג קָדָם יְיָ אֱלָהָךְ בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אֲרֵי יְבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכָל עֲלַלְתָּךְ וּבְכָל עוֹבָדֵי יְדָיךְ וּתְהֵי בְּרַם חָדֵי:
@125 תְּלַת זִמְנִין בְּשַׁתָּא יִתְחֲזֵי כָל דְכוּרָךְ קֳדָם יְיָ אֱלָהָךְ בְּאַתְרָא דִי יִתִּרְעֵי בְּחַגָא דְפַטִירַיָא וּבְחַגָא דְשָׁבוּעַיָא וּבְחַגָא דִמְטָּלַיָא וְלָא יִתְחֲזֵי קֳדָם יְיָ רֵיקָנוּן:
@126 גְבַר כְּמַתְּנַת יְדֵהּ כְּבִרְכָּתָא דַיְיָ אֱלָהָךְ דִי יְהַב לָךְ: ססס:

@1 **ראה אנכי נתן לפניכם היום ברכה וקללה.** האמורות בהר גרזים ובהר עיבל:
@2 **את הברכה.** על מנת אשר תשמעו:
@3 **מן הדרך אשר אנכי מצוה אתכם היום ללכת** וגו' **.** הא למדת שכל העובד עבודה זרה הרי הוא סר מכל הדרך שנצטוו ישראל. מכאן אמרו כל המודה בעבודה זרה ככופר בכל התורה כלה:
@4 **ונתתה את הברכה.** כתרגומו ית מברכיא, את המברכים: **על הר גרזים.** כלפי הר גרזים, הופכין פניהם ופתחו בברכה, ברוך האיש אשר לא יעשה פסל ומסכה וגו' . כל הארורים שבפרשה אמרו תחלה בלשון ברוך, ואחר כך הפכו פניהם כלפי הר עיבל ופתחו בקללה:
@5 **הלא המה.** נתן בהם סימן: **אחרי.** אחרי העברת הירדן הרבה והלאה למרחוק. וזהו לשון אחרי. כל מקום שנאמר אחרי, מפלג הוא: **דרך מבוא השמש.** להלן מן הירדן לצד מערב. וטעם המקרא מוכיח שהם שני דברים, שננקדו בשני טעמים, אחרי, נקוד בפשטא, ודרך, נקוד במשפל והוא דגש, ואם היה אחרי דרך, דבור אחד, היה נקוד אחרי, במשרת, בשופר הפוך, ודרך, בפשטא ורפה: **מול הגלגל.** רחוק מן הגלגל: **אלוני מרה.** שכם הוא, שנאמר (בראשית יב, ו) עד מקום שכם עד אלון מרה:
@6 **כי אתם עברים את הירדן** וגו' **.** נסים של ירדן יהיו סימן בידכם שתבואו ותירשו את הארץ:
@9 **אבד תאבדון.** אבד ואחר כך תאבדון מכאן לעוקר עבודה זרה שצריך לשרש אחריה: **את כל המקומות אשר עבדו שם** וגו' **.** ומה תאבדון מהם, את אלהיהם אשר על ההרים:
@10 **מזבח.** של אבנים הרבה: **מצבה.** של אבן אחת, והוא בימוס ששנויה במשנה (ע''ז מז, ב) אבן שחצבה מתחלתה לבימוס: **אשרה.** אילן הנעבד: **ואבדתם את שמם.** לכנות להם שם לגנאי, בית גליא קורין לה בית כריא, עין כל עין קוץ:
@11 **לא תעשון כן.** להקטיר לשמים בכל מקום (פסוק ה) , כי אם במקום אשר יבחר. דבר אחר ונתצתם את מזבחתם ואבדתם את שמם לא תעשון כן, אזהרה למוחק את השם ולנותץ אבן מן המזבח או מן העזרה. אמר רבי ישמעאל וכי תעלה על דעתך שישראל נותצין את המזבחות, אלא שלא תעשו כמעשיהם, ויגרמו עונותיכם למקדש אבותיכם שיחרב:
@12 **לשכנו תדרשו.** זה משכן שילה:
@13 **וזבחיכם.** שלמים של חובה: **מעשרתיכם.** מעשר בהמה ומעשר שני לאכול לפנים מן החומה: **תרומת ידכם.** אלו הבכורים, שנאמר בהם (דברים כו, ד) ולקח הכהן הטנא מידך: **ובכורות בקרכם.** לתתם לכהן ויקריבם שם:
@14 **אשר ברכך ה'.** לפי הברכה הבא:
@15 **לא תעשון ככל אשר אנחנו עשים** וגו' **.** מוסב למעלה (דברים יא, לא) על כי אתם עברים את הירדן וגו' כשתעברו את הירדן, מיד מתרים אתם להקריב בבמה, כל ארבע עשרה שנה של כבוש וחלוק, ובבמה לא תקריבו כל מה שאתם מקריבים פה היום במשכן, שהוא עמכם ונמשח והוא כשר להקריב בו חטאות ואשמות נדרים ונדבות, אבל בבמה אין קרב אלא הנדר והנדב. וזהו איש כל הישר בעיניו, נדרים ונדבות שאתם מתנדבים על ידי שיישר בעיניכם להביאם ולא על ידי חובה, אותם תקריבו בבמה:
@16 **כי לא באתם.** כל אותן ארבע עשרה שנה: **אל המנוחה.** זו שילה: **הנחלה.** זו ירושלים: **עד עתה.** כמו עדין:
@17 **ועברתם את הירדן וישבתם בארץ.** משתחלקוה ויהא כל אחד מכיר את חלקו ואת שבטו: **והניח לכם.** לאחר כבוש וחלוק ומנוחה (שופטים ג, א) מן הגוים אשר הניח ה' לנסות בם את ישראל. ואין זאת אלא בימי דוד, אז:
@18 **והיה המקום** וגו' **.** בנו לכם בית הבחירה בירושלים. וכן הוא אומר בדוד (שמואל ב' ז, א. ב) ויהי כי ישב המלך בביתו, וה' הניח לו מסביב מכל אויביו. ויאמר המלך אל נתן הנביא ראה נא אנכי יושב בבית ארזים, וארון האלהים ישב בתוך היריעה: **שמה תביאו** וגו' **.** למעלה אמרו (פסוק ו) לענין שילה וכאן אמור לענין ירושלים, ולכך חלקם הכתוב, לתן התר בין זו לזו, משחרבה שילה ובאו לנוב, וחרבה נוב ובאו לגבעון, היו הבמות מתרות עד שבאו לירושלים: **מבחר נדריכם.** מלמד שיביאו מן המבחר:
@20 **השמר לך.** לתן לא תעשה על הדבר. **בכל מקום אשר תראה.** אשר יעלה בלבך, אבל אתה מקריב על פי נביא, כגון אליהו בהר הכרמל:
@21 **באחד שבטיך.** בחלקו של בנימין. ולמעלה הוא אומר (פסוק ה) מכל שבטיכם. הא כיצד, כשקנה דוד את הגרן מארונה היבוסי גבה הזהב מכל השבטים, ומכל מקום הגרן בחלקו של בנימין היה:
@22 **רק בכל אות נפשך.** במה הכתוב מדבר, אם בבשר תאוה להתירה להם בלא הקרבת אמורים, הרי הוא אומר במקום אחר (פסוק כ) כי ירחיב ה' אלהיך את גבולך וגו' ואמרת אכלה בשר וגו', במה זה מדבר, בקדשים שנפל בהם מום, שיפדו ויאכלו בכל מקום. יכול יפדו על מום עובר, תלמוד לומר רק: **תזבח ואכלת.** אין לך בהם התר גזה וחלב, אלא אכילה על ידי זביחה: **הטמא והטהור.** לפי שבאו מכח קדשים, שנאמר בהם (ויקרא ז, יט) והבשר אשר יגע בכל טמא לא יאכל, הצרך להתיר בו, שטמא וטהור אוכלין בקערה אחת: **כצבי וכאיל.** שאין קרבן בא מהם: **כצבי וכאיל.** לפטרן מן הזרוע והלחיים והקבה:
@23 **רק הדם לא תאכלו.** אף על פי שאמרתי שאין לך בו זריקת דם במזבח, לא תאכלנו: **תשפכנו כמים.** לומר לך שאין צריך כסוי. דבר אחר הרי הוא כמים להכשיר את הזרעים:
@24 **לא תוכל.** בא הכתוב לתן לא תעשה על הדבר. רבי יהושע בן קרחה אומר יכול אתה, אבל אינך רשאי, כיוצא בו (יהושע טו, סג) ואת היבוסי יושבי ירושלים לא יכלו בני יהודה להורישם, יכולים היו, אלא שאינן רשאין, לפי שכרת להם אברהם ברית כשלקח מהם מערת המכפלה. ולא יבוסים היו אלא חתיים היו, אלא על שם העיר ששמה יבוס [נקראים יבוסים] . כך מפורש בפרקי דרבי אליעזר. והוא שנאמר (שמואל ב' ה, ו) כי אם הסירך העורים והפסחים, צלמים שכתבו עליהם את השבועה: **ובכרת בקרך.** אזהרה לכהנים: **ותרומת ידך.** אלו הבכורים:
@25 **לפני ה'.** לפנים מן החומה: **והלוי אשר בשעריך.** אם אין לך לתת לו מחלקו, כגון מעשר ראשון, תן לו מעשר עני. אין לך מעשר עני, הזמינהו על שלמיך:
@26 **השמר לך.** לתן לא תעשה על הדבר: **על אדמתך.** אבל בגולה אינך מזהר עליו יותר מעניי ישראל:
@27 **כי ירחיב** וגו' **.** למדה תורה דרך ארץ, שלא יתאוה אדם לאכול בשר, אלא מתוך רחבת ידים ועושר: **בכל אות נפשך** וגו' **.** אבל במדבר נאסר להם בשר חלין, אלא אם כן מקדישה ומקריבה שלמים:
@28 **כי ירחק ממך המקום.** ולא תוכל לבוא ולעשות שלמים בכל יום כמו עכשיו שהמשכן הולך עמכם: **וזבחת** וגו' **כאשר צויתך.** למדנו שיש צווי בזביחה היאך ישחוט, והן הלכות שחיטה שנאמרו למשה בסיני:
@29 **אך כאשר יאכל את הצבי** וגו' **.** אינך מזהר לאכלן בטהרה. אי מה צבי ואיל חלבן מתר, אף חלין חלבן מתר, תלמוד לומר אך:
@30 **רק חזק לבלתי אכל הדם.** ממה שנאמר חזק אתה למד שהיו שטופים בדם לאכלו, לפיכך הצרך לומר חזק, דברי רבי יהודה. רבי שמעון בן עזאי אומר, לא בא הכתוב אלא להזהירך וללמדך עד כמה אתה צריך להתחזק במצות, אם הדם, שהוא קל להשמר ממנו, שאין אדם מתאוה לו, הצרך לחזקך באזהרתו, קל וחמר לשאר מצות: **ולא תאכל הנפש עם הבשר.** אזהרה לאבר מן החי:
@31 **לא תאכלנו.** אזהרה לדם התמצית:
@32 **לא תאכלנו.** אזהרה לדם האיברים: **למען ייטב לך** וגו' **.** צא ולמד מתן שכרן של מצות, אם הדם שנפשו של אדם קצה ממנו, הפורש ממנו זוכה לו ולבניו אחריו, קל וחמר לגזל ועריות שנפשו של אדם מתאוה להם:
@33 **רק קדשיך.** אף על פי שאתה מתר לשחוט חלין, לא התרתי לך לשחוט את הקדשים ולאכלן בשעריך בלא הקרבה, אלא הביאם לבית הבחירה:
@34 **ועשית עלתיך.** אם עולות הם תן הבשר והדם על גבי המזבח, ואם זבחי שלמים הם, דם זבחיך ישפך על המזבח תחלה ואחר כך והבשר תאכל. ועוד דרשו רבותינו (פסוק כו) , רק קדשיך בא ללמד על הקדשים שבחוצה לארץ וללמד על התמורות ועל ולדות קדשים שיקריבו:
@35 **שמר.** זו משנה שאתה צריך לשמרה בבטנך שלא תשכח. כענין שנאמר (משלי כב) כי נעים כי תשמרם בבטנך, ואם שנית אפשר שתשמע ותקיים, הא כל שאינו בכלל משנה אינו בכלל מעשה: **את כל הדברים.** שתהא חביבה עליך מצוה קלה כמצוה חמורה: **הטוב.** בעיני השמים: **והישר.** בעיני אדם:
@37 **פן תנקש.** אנקלוס תרגם לשון מוקש. ואני אומר שלא חש לדקדק בלשון, שלא מצינו נו''ן בלשון יוקש ואפלו ליסוד הנופל ממנו, אבל בלשון טרוף וקשקוש מצינו נו''ן (דניאל ה, ו) וארכבתה דא לדא נקשן. ואף זה אני אומר, פן תנקש אחריהם פן תטרף אחריהם להיות כרוך אחר מעשיהם, וכן (תהלים קט, יא) ינקש נושה לכל אשר לו, מקלל את הרשע להיות עליו נושים רבים והיו מחזירין ומנקשין אחר ממונו: **אחרי השמדם מפניך.** אחר שתראה שאשמידם מפניך, יש לך לתת לב מפני מה נשמדו אלו, מפני מעשים מקלקלים שבידיהם, אף אתה לא תעשה כן שלא יבואו אחרים וישמידוך: **איכה יעבדו.** לפי שלא ענש על עבודת אלילים אלא על זבוח וקטור ונסוך והשתחואה, כמו שכתוב (שמות כב, יט) בלתי לה' לבדו, דברים הנעשים לגבוה, בא ולמדך כאן, שאם דרכה של עבודה זרה לעבדה בדבר אחר, כגון פוער לפעור, וזורק אבן למרקוליס, זו היא עבודתה וחיב. אבל זבוח וקטור ונסוך והשתחואה, אפלו שלא כדרכה חיב:
@38 **כי גם את בניהם.** גם, לרבות את אבותיהם ואמותיהם. אמר ר' עקיבא אני ראיתי נכרי שכפתו לאביו לפני כלבו ואכלו:
@39 **את כל הדבר.** קלה כחמורה: **תשמרו לעשות.** לתן לא תעשה על עשה האמורים בפרשה. שכל השמר לשון לא תעשה הוא, אלא שאין לוקין על השמר של עשה: **לא תסף עליו.** חמשה טוטפות בתפלין, חמשה מינין בלולב, ארבע ברכות בברכת כהנים:
@40 **ונתן אליך אות.** בשמים, כענין שנאמר בגדעון (שופטים ו, יז) ועשית לי אות, ואומר (שם ו, לט) יהי נא חרב אל הגזה וגו' : **או מופת.** בארץ. [ ס''א אות . בשמים , דכתיב (בראשית א, יד) והיו לאתת ולמועדים או מופת . בארץ . דכתיב (שופטים שם) אם טל יהיה על הגזה לבדה ועל כל הארץ חרב ] אף על פי כן לא תשמע לו. ואם תאמר מפני מה נותן לו הקדוש ברוך הוא ממשלה לעשות אות, כי מנסה ה' אלהיכם אתכם:
@43 **ואת מצותיו תשמרו.** תורת משה: **ובקולו תשמעו.** בקול הנביאים: **ואתו תעבדו.** במקדשו: **ובו תדבקון.** הדבק בדרכיו. גמול חסדים, קבור מתים, בקר חולים, כמו שעשה הקדוש ברוך הוא:
@44 **סרה.** דבר המוסר מן העולם שלא היה ולא נברא ולא צויתיו לדבר כן, דישטולוד''א בלע''ז : **והפדך מבית עבדים.** אפלו אין לו עליך אלא שפדאך, דיו:
@45 **כי יסיתך.** אין הסתה אלא גרוי, שנאמר (שמואל א' כו, יט) אם ה' הסיתך בי, אמיטר''א בלע''ז , שמשיאו לעשות כן: **אחיך.** מאב: **בן אמך.** מאם: **חיקך.** השוכבת בחיקך ומחקה בך אפיקייד''א בלע''ז , וכן (יחזקאל מג, יד) ומחיק הארץ, מיסוד התקוע בארץ: **אשר כנפשך.** זה אביך. פרש לך הכתוב את החביבין לך, קל וחמר לאחרים: **בסתר.** דבר הכתוב בהוה, שאין דברי מסית אלא בסתר. וכן שלמה הוא אומר (משלי ז, ט) בנשף בערב יום באישון לילה ואפלה: **אשר לא ידעת אתה ואבתיך.** דבר זה גנאי גדול הוא לך שאף האמות אין מניחין מה שמסרו להם אבותיהם, וזה אומר לך עזוב מה שמסרו לך אבתיך:
@46 **הקרבים אליך או הרחקים.** למה פרט קרובים ורחוקים, אלא כך אמר הכתוב, מטיבן של קרובים אתה למד טיבן של רחוקים, כשם שאין ממש בקרובים כך אין ממש ברחוקים: **מקצה הארץ.** זו חמה ולבנה וצבא השמים שהן מהלכין מסוף העולם ועד סופו:
@47 **לא תאבה לו.** לא תהא תאב לו. לא תאהבנו. לפי שנאמר (ויקרא יט, יח) ואהבת לרעך כמוך, את זה לא תאהב: **ולא תשמע אליו.** בהתחננו על נפשו למחול לו, לפי שנאמר (שמות כג, ה) עזב תעזב עמו, לזה לא תעזוב: **ולא תחוס עינך עליו.** לפי שנאמר (ויקרא יט, טז) לא תעמד על דם רעך, על זה לא תחוס: **ולא תחמול.** לא תהפך בזכותו: **ולא תכסה עליו.** אם אתה יודע לו חובה אינך רשאי לשתוק:
@48 **כי הרג תהרגנו.** אם יצא מבית דין זכאי, החזירהו לחובה. יצא מבית דין חיב, אל תחזירהו לזכות: **ידך תהיה בו בראשונה.** מצוה ביד הנסת להמיתו. לא מת בידו, ימות ביד אחרים, שנאמר ויד כל העם וגו' :
@51 **לשבת שם.** פרט לירושלים שלא נתנה לדירה: **כי תשמע** וגו' **לאמר.** אומרים כן, יצאו וגו' :
@52 **בני בליעל.** בלי עול. שפרקו עלו של מקום: **אנשים.** ולא נשים: **ישבי עירם.** ולא יושבי עיר אחרת. מכאן אמרו אין נעשית עיר הנדחת עד שידיחוה אנשים, ועד שיהיו מדיחיה מתוכה:
@53 **ודרשת וחקרת ושאלת היטב.** מכאן למדו שבע חקירות מרבוי המקרא. כאן יש שלש דרישה וחקירה והיטב. ושאלת, אינו מן המנין, וממנו למדו בדיקות. ובמקום אחר הוא אומר (דברים יט, יח) ודרשו השופטים היטב. ועוד במקום אחר הוא אומר (שם יז, ד) ודרשת היטב. ולמדו היטב היטב לגזרה שוה, לתן האמור של זה בזה:
@54 **הכה תכה.** אם אינך יכול להמיתם במיתה הכתובה בהם, המיתם באחרת:
@55 **לה' אלהיך.** לשמו ובשבילו:
@56 **למען ישוב ה' מחרון אפו.** שכל זמן שעבודה זרה בעולם, חרון אף בעולם:
@58 **לא תתגדדו.** לא תתנו גדידה ושרט בבשרכם על מת כדרך שהאמוריים עושין, לפי שאתם בניו של מקום ואתם ראויין להיות נאים ולא גדודים ומקורחים: **בין עיניכם.** אצל הפדחת. ובמקום אחר הוא אומר (ויקרא כא, ה) לא יקרחו קרחה בראשם, לעשות כל הראש כבין העינים:
@59 **כי עם קדוש אתה.** קדשת עצמך מאבותיך. ועוד, ובך בחר ה':
@60 **כל תועבה.** כל שתעבתי לך, שאם צרם אזן בכור כדי לשחטו במדינה, הרי דבר שתעבתי לך כל מום לא יהיה בו, ובא ולמד כאן שלא ישחט ויאכל על אותו המום. בשל בשר בחלב הרי דבר שתעבתי לך, והזהיר כאן על אכילתו:
@62 **זאת הבהמה** וגו'' **איל וצבי ויחמור.** למדנו שהחיה בכלל בהמה, ולמדנו שבהמה וחיה טמאה מרבה מן הטהורה, שבכל מקום פורט את המועט: **ואקו.** מתרגם יעלא (איוב לט, א) יעלי סלע הוא אשטנבו''ק : **ותאו.** תורבלא, שור היער. באלא יער, בלשון ארמי:
@63 **מפרסת.** סדוקה כתרגומו: **פרסה.** פלנט''א [כף רגל] : **ושסעת.** חלוקה בשתי צפרנים. שיש סדוקה ואינה חלוקה בצפרנים והיא טמאה: **בבהמה.** משמע מה שנמצא בבהמה אכל, מכאן אמרו שהשליל נתר בשחיטת אמו:
@64 **השסועה.** בריה היא שיש לה שני גבין ושתי שדראות. אמרו רבותינו למה נשנו, בבהמות מפני השסועה, ובעופות מפני הראה, שלא נאמרו בתורת כהנים:
@65 **ובנבלתם לא תגעו.** רבותינו פרשו, ברגל. שאדם חיב לטהר את עצמו ברגל. יכול יהיו מזהרים בכל השנה, תלמוד לומר (ויקרא כא, א) אמור אל הכהנים וגו' ומה טמאת המת חמורה, כהנים מזהרים ואין ישראל מזהרים, טמאת נבלה קלה לא כל שכן:
@68 **כל צפור טהורה תאכלו.** להתיר משלחת שבמצורע:
@69 **וזה אשר לא תאכלו מהם.** לאסר את השחוטה:
@70 **והראה ואת האיה** וגו' **.** היא ראה היא איה היא דיה. ולמה נקרא שמה ראה, שרואה ביותר. ולמה הזהיר בכל שמותיה, שלא לתן פתחון פה לבעל דין לחלוק, שלא יהא האוסרה קורא אותה ראה והבא להתיר אומר, זו דיה שמה או איה שמה, וזו לא אסר הכתוב. ובעופות פרט לך הטמאים, ללמד שהעופות הטהורים מרבים על הטמאים, לפיכך פרט את המועט:
@73 **והתנשמת.** קלב''א שורי''ץ :
@74 **שלך.** השולה דגים מן הים:
@75 **דוכיפת.** הוא תרנגול הבר ובלע''ז הרופ''א וכרבלתו כפולה:
@76 **שרץ העוף.** הם הנמוכים הרוחשים על הארץ, כגון זבובין וצרעים וחגבים טמאים, הם קרויים שרץ:
@77 **כל עוף טהור תאכלו.** ולא את הטמא. בא לתן עשה על לא תעשה. וכן בבהמה, אותה תאכלו ולא בהמה טמאה, לאו הבא מכלל עשה, עשה, לעבור עליהם בעשה ולא תעשה:
@78 **לגר אשר בשעריך.** גר תושב שקבל עליו שלא לעבוד עבודה זרה ואוכל נבלות: **כי עם קדוש אתה לה'.** קדש את עצמך במתר לך. דברים המתרים ואחרים נוהגים בהם אסור, אל תתירם בפניהם: **לא תבשל גדי.** שלש פעמים. פרט לחיה ולעופות ולבהמה טמאה: **לא תבשל גדי** וגו':
@79 **עשר תעשר.** מה ענין זה אצל זה, אמר להם הקדוש ברוך הוא לישראל, לא תגרמו לי לבשל גדיים של תבואה עד שהן במעי אמותיהן, שאם אין אתם מעשרים מעשרות כראוי, כשהוא סמוך להתבשל אני מוציא רוח קדים והיא משדפתן. שנאמר (מלכים ב' יט, כא) ושדפה לפני קמה, וכן לענין בכורים: **שנה שנה.** מכאן שאין מעשרין מן החדש על הישן:
@80 **ואכלת** וגו' **.** זה מעשר שני. שכבר למדנו לתן מעשר ראשון ללוים, שנאמר (במדבר יח, כו) כי תקחו מאת בני ישראל וגו' , ונתן להם רשות לאכלו בכל מקום, שנאמר (שם יח, לא) ואכלתם אתו בכל מקום, על כרחך זה מעשר אחר הוא:
@81 **כי יברכך.** שתהא התבואה מרבה לשאת:
@83 **בכל אשר תאוה נפשך.** כלל: **בבקר ובצאן וביין ובשכר.** פרט: **ובכל אשר תשאלך נפשך.** חזר וכלל. מה הפרט מפורש ולד ולדות הארץ וראוי למאכל אדם וכו' :
@84 **והלוי** וגו' **לא תעזבנו.** מלתן לו מעשר ראשון: **כי אין לו חלק ונחלה עמך.** יצאו לקט שכחה ופאה והפקר, שאף הוא יש לו חלק עמך בהן כמוך, ואינן חיבין במעשר:
@85 **מקצה שלש שנים.** בא ולמד שאם השהה מעשרותיו של שנה ראשונה ושניה לשמטה, שיבערם מן הבית בשלישית:
@86 **ובא הלוי.** ויטול מעשר ראשון: **והגר והיתום.** ויטלו מעשר שני, שהוא של עני של שנה זו, ולא תאכלנו אתה בירושלים כדרך שנזקקת לאכול מעשר שני של שתי שנים: **ואכלו ושבעו.** תן להם כדי שביעה. מכאן אמרו אין פוחתין לעני בגורן וכו' . ואתה הולך לירושלים למעשר של שנה ראשונה ושניה שהשהית ומתודה בערתי הקדש מן הבית (דברים כו, יג) , כמו שמפורש ב''כי תכלה לעשר'' (שם כו, יב) :
@87 **מקץ שבע שנים.** יכול שבע שנים לכל מלוה ומלוה, תלמוד לומר (פסוק ט) קרבה שנת השבע. ואם אתה אומר שבע שנים לכל מלוה ומלוה להלואת כל אחד ואחד, היאך היא קרבה, הא למדת שבע שנים למנין השמטות:
@88 **שמוט כל בעל משה ידו.** שמוט את ידו של כל בעל משה:
@89 **את הנכרי תגש.** זו מצות עשה:
@90 **אפס כי לא יהיה בך אביון.** ולהלן הוא אומר (פסוק יא) כי לא יחדל אביון, אלא בזמן שאתם עושים רצונו של מקום, אביונים באחרים ולא בכם, וכשאין אתם עושים רצונו של מקום אביונים בכם: **אביון.** דל מעני, ולשון אביון שהוא תאב לכל דבר:
@91 **רק אם שמוע תשמע.** אז לא יהיה בך אביון: **שמוע תשמע.** שמע קמעא משמיעין אותו הרבה:
@92 **כאשר דבר לך.** והיכן דבר, ברוך אתה בעיר: (דברים כח, ג) **והעבטת.** כל לשון הלואה כשנופל על המלוה, נופל בלשון מפעיל. כגון והלוית, והעבטת. ואם היה אומר ועבטת היה נופל על הלוה, כמו ולוית: **והעבטת גוים.** יכול שתהא לוה מזה ומלוה לזה, תלמוד לומר ואתה לא תעבט: **ומשלת בגוים רבים.** יכול גוים אחרים מושלים עליך, תלמוד לומר ובך לא ימשלו:
@93 **כי יהיה בך אביון.** התאב תאב קודם: **מאחד אחיך.** אחיך מאביך, קודם לאחיך מאמך: **שעריך.** עניי עירך קודמים לעניי עיר אחרת: **לא תאמץ.** יש לך אדם שמצטער אם יתן אם לא יתן, לכך נאמר לא תאמץ. יש לך אדם שפושט את ידו וקופצה, לכך נאמר ולא תקפץ: **מאחיך האביון.** אם לא תתן לו, סופך להיות אחיו בעניות [של אביון] :
@94 **פתח תפתח.** אפלו כמה פעמים: **כי פתח תפתח.** הרי כי משמש בלשון אלא: **והעבט תעביטנו.** אם לא רצה במתנה, תן לו בהלואה: **די מחסרו.** ואי אתה מצוה להעשירו: **אשר יחסר לו.** אפלו סוס לרכוב עליו ועבד לרוץ לפניו: **לו.** זו אשה. וכן הוא אומר (בראשית ב, יח) אעשה לו עזר כנגדו:
@95 **וקרא עליך.** יכול מצוה, תלמוד לומר (דברים כד, טו) ולא יקרא: **והיה בך חטא.** מכל מקום, אפלו לא יקרא. אם כן למה נאמר וקרא עליך, ממהר אני לפרע על ידי הקורא יותר ממי שאינו קורא:
@96 **נתון תתן לו.** אפלו מאה פעמים: **לו.** בינו ובינך: **כי בגלל הדבר.** אפלו אמרת לתן, אתה נוטל שכר האמירה עם שכר המעשה:
@97 **על כן.** מפני כן: **לאמר.** עצה לטובתך אני משיאך: **לאחיך לעניך.** לאיזה אח, לעני: **לעניך.** ביו''ד אחד, לשון עני אחד הוא. אבל ענייך בשני יודי''ן, שני עניים:
@98 **כי ימכר לך.** על ידי אחרים, שמכרוהו בית דין בגנבתו הכתוב מדבר. והרי כבר נאמר (שמות כא, ב) כי תקנה עבד עברי, ובמכרוהו בית דין הכתוב מדבר. אלא מפני שני דברים שנתחדשו כאן. אחד שכתוב או העבריה, אף היא תצא בשש. ולא שמכרוה בית דין, שאין האשה נמכרת בגנבתה, שנאמר בגנבתו ולא בגנבתה, אלא בקטנה שמכרה אביה, ולמד כאן שאם יצאו שש שנים קודם שתביא סימנין תצא. ועוד חדש כאן (פסוק יד) העניק תעניק:
@100 **העניק תעניק.** לשון עדי בגובה ובמראית העין, שיהא נכר שהטיבות לו. ויש מפרשים לשון הטענה על צוארו: **מצאנך ומגרנך ומיקבך.** יכול אין לי אלא אלו בלבד, תלמוד לומר אשר ברכך, מכל מה שברכך בוראך. ולמה נאמרו אלו, מה אלו מיוחדים שהם בכלל ברכה אף כל שהוא בכלל ברכה, יצאו פרדות. ולמדו רבותינו במסכת קדושין (יז, א) בגזרה שוה כמה נותן לו מכל מין ומין:
@101 **וזכרת כי עבד היית.** והענקתי ושניתי לך מבזת מצרים ובזת הים, אף אתה הענק ושנה לו:
@103 **עבד עולם.** יכול כמשמעו, תלמוד לומר (ויקרא כה, י) ושבתם איש אל אחזתו ואיש אל משפחתו תשובו, הא למדת שאין זה, אלא עולמו של יובל: **ואף לאמתך תעשה כן.** הענק לה. יכול אף לרציעה השוה הכתוב אותה, תלמוד לומר (שמות כא, ה) ואם אמר יאמר העבד, עבד נרצע, ואין אמה נרצעת:
@104 **כי משנה שכר שכיר.** מכאן אמרו עבד עברי עובד בין ביום ובין בלילה. וזהו כפלים שבעבודת שכירי יום. ומהו עבודתו בלילה, רבו מוסר לו שפחה כנענית והולדות לאדון:
@105 **כל הבכור** וגו' **תקדיש.** ובמקום אחר הוא אומר לא יקדיש, שנאמר (ויקרא כז, כו) אך בכור אשר יבכר לה' וגו' , הא כיצד, אינו מקדישו לקרבן אחר, וכאן למד שמצוה לומר הרי אתה קדוש לבכורה. דבר אחר אי אפשר לומר תקדיש שכבר נאמר לא יקדיש, ואי אפשר לומר לא יקדיש שהרי כבר נאמר תקדיש, הא כיצד, מקדישו אתה הקדש עלוי, ונותן להקדש כפי טובת הנאה שבו: **לא תעבד בבכור שורך ולא תגז** וגו' **.** אף החלוף למדו רבותינו שאסור, אלא שדבר הכתוב בהוה:
@106 **לפני ה' אלהיך תאכלנו.** לכהן הוא אומר, שכבר מצינו שהוא ממתנות כהנה אחד תם ואחד בעל מום, שנאמר (במדבר יח, יח) ובשרם יהיה לך וגו' : **שנה בשנה.** מכאן שאין משהין אותו יותר על שנתו. יכול יהא פסול משעברה שנתו, כבר הקש למעשר, שנאמר (לעיל יד, כג) ואכלת לפני ה' אלהיך מעשר דגנך תירשך ויצהרך ובכרת בקרך וצאנך, מה מעשר שני אינו נפסל משנה לחברתה, אף בכור אינו נפסל, אלא שמצוה תוך שנתו: **שנה בשנה.** אם שחטו בסוף שנתו, אוכלו אותו היום ויום אחד משנה אחרת. למד שנאכל לשני ימים ולילה אחד:
@107 **מום.** כלל: **פסח או עור.** פרט: **כל מום רע.** חזר וכלל. מה הפרט מפורש מום הגלוי ואינו חוזר, אף כל מום שבגלוי ואינו חוזר:
@109 **רק את דמו לא תאכל.** שלא תאמר הואיל וכלו התר הבא מכלל אסור הוא, שהרי קדוש ונשחט בחוץ בלא פדיון ונאכל, יכול יהא אף הדם מתר, תלמוד לומר רק את דמו לא תאכל:
@110 **שמור את חדש האביב.** מקודם בואו שמור, שיהא ראוי לאביב להקריב בו את מנחת העמר, ואם לאו, עבר את השנה: **ממצרים לילה.** והלא ביום יצאו, שנאמר (במדבר לג, ג) ממחרת הפסח יצאו בני ישראל וגו' , אלא לפי שבלילה נתן להם פרעה רשות לצאת, שנאמר (שמות יב, לא) ויקרא למשה ולאהרן לילה וגו' :
@111 **וזבחת פסח לה' אלהיך צאן.** שנאמר (שמות יב, ה) מן הכבשים ומן העזים תקחו: **ובקר.** תזבח לחגיגה. שאם נמנו על הפסח חבורה מרבה, מביאים עמו חגיגה כדי שיהא נאכל על השובע, ועוד למדו רבותינו דברים הרבה מפסוק זה:
@112 **לחם עני.** לחם שמזכיר את העוני שנתענו במצרים: **כי בחפזון יצאת.** ולא הספיק בצק להחמיץ וזה יהיה לך לזכרון. וחפזון לא שלך היה אלא של מצרים, שכן הוא אומר (שמות יב, לג) ותחזק מצרים על העם וגו' : **למען תזכר.** על ידי אכילת הפסח והמצה, את יום צאתך:
@113 **ולא ילין מן הבשר אשר תזבח בערב ביום הראשון לבקר.** אזהרה למותיר בפסח דורות, לפי שלא נאמר אלא בפסח מצרים, ויום ראשון האמור כאן הוא ארבעה עשר בניסן, כמה דאתאמר (שמות יב, טו) אך ביום הראשון תשביתו שאר מבתיכם. ולפי שנסתלק הכתוב מענינו של פסח והתחיל לדבר בחקות שבעת ימים, כגון שבעת ימים תאכל עליו מצות ולא יראה לך שאור בכל גבולך, הצרך לפרש באיזו זביחה הוא מזהיר, שאם כתב ולא ילין מן הבשר אשר תזבח בערב לבקר הייתי אומר שלמים הנשחטים כל שבעה כלן בבל תותירו ואינן נאכלין אלא ליום ולילה, לכך כתב בערב ביום הראשון. דבר אחר בחגיגת ארבעה עשר הכתוב מדבר, ולמד עליה שנאכלת לשני ימים. והראשון האמור כאן, ביום טוב הראשון הכתוב מדבר. וכן משמעות המקרא, בשר חגיגה אשר תזבח בערב, לא ילין ביום טוב הראשון עד בקרו של שני, אבל נאכלת היא בארבעה עשר ובחמשה עשר, כך היא שנויה במסכת פסחים (עא ב) :
@115 **בערב כבוא השמש מועד צאתך ממצרים.** הרי שלשה זמנים חלוקים, בערב, משש שעות ולמעלה זבחהו. וכבוא השמש, תאכלהו. ומועד צאתך, אתה שורפהו. כלומר, נעשה נותר ויצא לבית השרפה:
@116 **ובשלת.** זהו צלי אש, שאף הוא קרוי בשול: **ופנית בבקר.** לבקרו של שני, מלמד שטעון לינה ליל של מוצאי יום טוב:
@117 **ששת ימים תאכל מצות.** ובמקום אחר הוא אומר (שמות יב, טו) שבעת ימים, שבעה מן הישן וששה מן החדש. דבר אחר למד על אכילת מצה בשביעי, שאינה חובה, ומכאן אתה למד לששת ימים. שהרי שביעי בכלל היה ויצא מן הכלל ללמד, שאין אכילת מצה בו חובה אלא רשות, ולא ללמד על עצמו יצא אלא ללמד על הכלל כלו יצא, מה שביעי רשות אף כלם רשות, חוץ מלילה הראשון שהכתוב קבעו חובה, שנאמר (שמות יב, יח) בערב תאכלו מצות: **עצרת לה' אלהיך.** עצור עצמך מן המלאכה. דבר אחר כנופיא של מאכל ומשתה, לשון (שופטים יג, טו) נעצרה נא אותך:
@118 **מהחל חרמש בקמה.** משנקצר העמר שהוא ראשית הקציר:
@119 **מסת נדבת ידך.** די נדבת ידך, הכל לפי הברכה, הבא שלמי שמחה, וקדש קרואים לאכול:
@120 **והלוי:. והגר והיתום והאלמנה.** ארבעה שלי כנגד ארבעה שלך, בנך ובתך ועבדך ואמתך, אם אתה משמח את שלי, אני משמח את שלך:
@121 **וזכרת כי עבד היית** וגו' **.** על מנת כן פדיתיך, שתשמור ותעשה את החקים האלה:
@122 **באספך.** בזמן האסיף שאתה מכניס לבית פרות הקיץ. דבר אחר באספך מגרנך ומיקבך, למד שמסככין את הסכה בפסולת גורן ויקב:
@124 **והיית אך שמח.** לפי פשוטו אין זה לשון צווי אלא לשון הבטחה, ולפי תלמודו למדו מכאן לרבות לילי יום טוב האחרון לשמחה:
@125 **ולא יראה את פני ה' ריקם.** אלא הבא עולות ראיה ושלמי חגיגה:
@126 **איש כמתנת ידו.** מי שיש לו אוכלין הרבה ונכסים מרבין יביא עולות מרבות ושלמים מרבים:
@127 **סוערה.** שלבה סוער ברובי צרות: **מרביץ בפוך.** רוצף רצפתך מאבני נופך:
@128 **כדכד.** מין אבן טובה: **שמשותיך.** י"ת אמך ומנחם חברו עם ישמשוניה ויש פותרין ל' שמש חלונות שחמה זורחת בהן ועושין כנגדו מחיצה במיני זכוכית צבעים לנוי ומדרש תהלים פותר שמשותיך ושמש ומגן ( תהלים פד ) שיני החומה: **לאבני אקדח.** י"ת לאבני גמר גומרין תרגום גחלים פתר אקדח לשון קדחי אש והם מין אבנים טובות בוערות כלפידי' והוא קרבונקל"א לשון גחלת ויש פותרין ל' מקדח אבנים גדולות שכל חלל הפתח קדוח בתוכו והמזוזות והמפתן והסף כולן מתוך האבן הם: **לאבני חפץ.** לאבני צרוך:
@130 **רחקי מעושק.** כמו ( לעיל נב ) התנערי מעפר תרחקי מן העושקי' אותך ( רחקי מעושק תרחק מלעשוק בני אדם כדרך שעושים רשעים שאוספי' ממון מגזל אבל אתם לא תצרכו לגזול כי לא תיראו מדלות ועניות וממחתה כי לא תבא ולא תקר' אליך אברבנאל ) ( בצדקה שתעשה תהיה נכונה בגאולת עולם ותהיה רחוקה מעושק בני אדם כי לא תראי אפי' פחד ויראה לא יהיה לך מהם ותהיה רחוקה ממחתה שלא תקרב אליך, איל"ה שלוח' ):
@131 **הן גור יגור אפס מאותי.** הן ירא יירא ויגור מגזרת רעו' אותו שאין אני עמו הוא שעיר: **מי גר אתך.** מי אשר נאסף עליך למלחמה, או מי גר מי שנתגרה בך, ורבותינו פירשוהו בגרים לומ' שאין מקבלי' גרים לימות משיחנו ואף בפשוטו של מקרא יתכן מי שנעשו גרים אתך בעניותך עליך יפול בעשירותך כמו על פני כל אחיו נפל ( בראשית כה ):
@132 **הנה אנכי.** אשר בראתי חרש המתקן כלי ואני אשר בראתי משחית המחבלו כלו' אני הוא שגריתי בך את האוי' אני הוא שהתקנתי לו פורעניות: **ומוציא כלי למעשהו.** לצורך גומרו כל צורכו:
@133 **כל כלי יוצר.** כל כלי זיין אשר ילטשוהו ויחדדהו בשבילך להלחם בך: **יוצר.** ל' חרבות צורים ( יהושע ה ) אף תשיב צור חרבו ( תהלים פט ):
@134 **הוי כל צמא.** הוי זה ל' קריאה וזימון וקיבוץ הוא ויש הרבה במקרא ( זכריה ב ) הוי הוי ונוסו מארץ צפון: **לכו למים.** לתורה: **שברו.** ל' לשבור בר ( בראשית מב ) קנו: **יין וחלב.** לקח טוב מיין וחלב:
@135 **למה תשקלו כסף.** למה תגרמו לכם לשקול כסף לאויביכם בלא לחם:
@136 **חסדי דוד.** שאגמול לדוד חסדיו:
@137 **לאומים.** שר וגדול עליהם ומוכיח ומעיד דרכיהם על פניהם:
@138 **הן גוי לא תדע תקרא.** לשמושך אם אלי תשמעו לשם ה' הנקרא עליך:

@1 **זכר** שכבר נתן השם יתעלה לפני ישראל ברכה וקללה והענין הוא בבחירתם וזה שאם ישמעו אל מצות השם אתעלה תבא להם הברכה והקללה אם לא ישמעו אל מצותיו:
@3 **וסרתם מן הדרך אשר אנכי מצוה אתכם ללכת אחרי אלהים אחרים.** ידענו שכבר היו שם קללות כשיעברו על אחת משארנין המצו' ואף על פי שלא יעבדו עבודה זרה כמו שנזכר מענין או הקללות בפרשת כי תבא ולזה יהיה הרצון בזה שאם יסורו ממצוה אחת ממצות התורה הנה יהיה זה סבה אל שיעבדו עבודה זרה כי זה יהיה סבה אל שיקלו במצות התורה ויעברו על החמורות אחר עברם על הקלות:
@4 **והיה כי יביאך וגו'.** כבר נתבאר בפשרת כי תבא שזאת המצוה נתחייבו בה תכף כניסתם לאר אחר עברם הירדן ולזה תמצא בספר יהושע כי אחר שהכה יהושע את יריחו ואת העי קיים זאת המצוה כמו שנתבאר מעניינה בפרשת כי תבא וזכר שם שכבר עשה יהושע כאשר צוה משה עבד יי' את בני ישראל ולזה הוא מבואר שמה שאמר בזה המקום והיה כי יביאך יי' אלהיך אל האר אין הרצון בו שימתינו שיירשו את הארץ אבל תכף שיוכלו לקיים זאת המצוה שם יקיימוהו ולזה לא אמר בזה וירשתם אותם וישבתם בה כמו שאמר במצות הנזכרות אחר זה וזה כי הכונה היתה בזה כדי שיהיו ישראל יותר זריזים בשמירת התורה מפני שמיעתם אלו הברכות והקללות ולפי שזריזותם בשמירת התורה היה לו מבוא עצום בירושתם את הארץ כמו שנזכר בזה הספר פעמים רבות חוייב שיעשו זה תכף היותם שליטים במקום ההוא אשר בו יקיימו זאת המצוה לפי מה שנתבאר מעניינה בפרשת כי תבא וכבר נתבאר זה גם כן שם באופן שלם כמו שיתבאר במה שיבא בג"ה:
@4 **ונתת את הברכה על הר גריזים ואת הקללה על הר עיבל.** למדנו מזה שבאופן שיתן הברכה על הר גריזים יתן הקללה למול הר עיבל וכבר התבאר בפרשת כי תבא שנתינת הקללה למול הר עיבל תהיה תחלה בפרט לעובר על מצוה אחת מהמצות הנזכרות שם ואחר כך תהיה בכלל וכן הענין בנתינת הברכה למול הר גריזים כי כבר תהיה בפרט כשיאמרו ברוך למי שמקיים המצוה על כל ארור שכתב תחילה בפרשת כי תבא למי שיעבור על המצוה ההיא וכבר תהיה הברכה על הפרטי' קודמת על הקללה על הפרטים כמו שמצאנו שם הברכה על הכלל היא קודמת לקללה על הכלל והנה היה הסדר כן שהלוים אמרו תחלה ברך על מי שמקיים פרט ופרט כנגד הר גריזים ואחר כך אמר ארור על כל מי שיעבור על כל פרט ופרט ואחר זה אמרו כל הברכות הנכתבות בפרשת כי תבא כנגד הר גריזים והם נאמרות בכלל על מי שמקיים וישמור מצות השם יתעלה ואחר זה הפכו פניהם למול הר עיבל ואמרו קללות והנכתבות שם בכלל למי שלא ישמע אל דבר התורה ולזה אמר בספר יהושע כאשר צוה משה עבד ה' לברך ישראל בראשונה ואחר כן קרא את דברי התורה הזאת הברכה והקללה. למדנו מזה שכבר ברכו העם בראשונה בברכות לא תכתבו בתורה ואחר כן קראו כל הכתו' בפרשת והיה כי תבא מהברכות והקללות על הסדר הכתוב שם ועוד למדנו מזה שכמו שנתבאר בקללות שהיו חלוף ביניהם אלא שהברכה היתה למול הר גריזים והקללה למול הר עיבל:
@5 **הלא המה בעבר הירדן אחרי דרך מבא השמש.** רוצה לומר שההרים האלו ימצאו כשיעברו את הירדן דר ךהולך ממזרח למערב כי לפאת מערב מהירדן היתה ארץ כנען והארץ אשר נתן לשני השבטים וחצי היתה מעבר הירדן מזרחה כמו שזכר במה שקדם ואולם למה נתן הברכה אצל הר גריזים והקללה אצל הע עיבל הנה לא אדע בה טעם אלא שלהראות עוצם ההבדל שיש בין הענינים האלו רצה להבדיל ביניהם עד שלא תהיה הקללה ואנשיה בצד שתהיה הברכה ואנשיה כי ההבדל בין שומרי התורה ובין העוברים על דבריה עצום מאד ולזה הוכרח אל שיתן הברכה לצד אחד והקללה לצד אחר ואם היינו יודעים צדדי אלו ההרים אולי היינו נותנים סבה מיוחדת למה תהיה הברכה אצל הר גריזים והקללה אצל הר עיבל והנה ידענו כי השם יתעלה צוה לבנות מזבח בהר עיבל ולכתוב שם משנה תורה באבנים שישדו בשיד והנה הושמה הקללה אצל הצד ההוא שיהיה בו המזבח והיה בו כתוב משנה תורה כדי שיתבארו להם דברים אשר עליהם היתה הקללה אם לא יקיימום כאלו יאמר שאם יעשו כמו זאת העבודה לא לשם יתעלה אם לא יקיימו משנה התורה הכתוב שם הנה תדבק הקללה בהם והנה זאת המצוה לא היתה אלא לפי שעה:
@6 **כי אתם עוברים את הירדן לבא לרשת את הארץ וגומ'.** ירצה לפי מה שאחשוב שכאשר יעברו את הירדן לבא לרשת את הארץ יקיימו זאת המצוה שזכר רוצה לומ' נתינת הברכה על הר גריזים והקללה על הר עיבל אמנם אח' שיירשו את האר' וישבו בה ישמרו לעשו' בה תמיד כל החקי' והמשפטי' אשר זכר אחר זה והוא לעקור ע"ז מארצם ושאר המצות הנמשכות לה אשר נוהגות באר לבד או בארץ ובחוצה לארץ ולא ינהגו בכניסתם לבד כמו הענין בזאת המצוה אך ינהגו תמיד קצתם באר לבד וקצתם בארץ ובחוצה לארץ או ירצה בזה שכבר הודיע להם שכאשר יעברו את הירדן לבא לרשת את הארץ שלא יתעכבו אחר זה בירושת הארץ כמו שנתעכבו במדבר עד שכבר הודיעם בזה שעברם את הירדן יישירם לבא לרשת את הארץ מצד המופת הנפלא שיעשה להם ה' ית' בעברם את הירדן שנתפרסם זה לכל מלכי האמורי אשר בעבר הירדן ימה והכנעני אשר על הים וימס לבבם ולא היה בהם עוד רוח מפני בני ישר' כמו שנזכר בספר יהושע עם שזה המופת הנפלא נעשה באופן שנתיישרו בו ישראל מאד להאמין בשם יתעלה שהיה מבא גדול לירושתם הארץ:
@7 **ושמרתם לעשות.** הנה מפני שלא ישמור לעשות מי שלא ידע מה שצוה הנה יחוייב מזה שילמדו המצות כדי שיעשום והנה השמירה היא בלב כמו הענין זכירה והכונה בזה שישמרו בלבם אלו המצות כדי שיתיישרו לעשותם בעת הצורך. כי הם נוהגות תמיד:
@7 **את כל החקים ואת כל המשפטים וגו'.** גם אחר שתירשו את הארץ ותשבו בה כי הם נוהגים תמיד והנה נוהגים קצתם בארץ לבד וקצתם נוהגים בין בארץ בין בחוצה לארץ:
@8 **אלה החקים והמשפטים אשר תשמרון לעשות בארץ.** זכה עתה החקים והמשפטים שנוהגים בארץ כל הימים תמיד שיהיו ישראל חיים על האדמה ההיא רצוני לומר בארץ ישראל:
@9 **אבד תאבדון את כל המקומו' אשר עבדו שם הגוים אשר אתם יורשים אותם וגו'.** הנה זאת המצוה היא לעקור עבודה זרה מארץ ישראל והיא נוהגת תמיד בכל עת שתמצא עבודה זרה שם והוא מבואר מענינה שאי אפשר בה שתנהג אלא בארץ ישראל כי כבר ביארה התורה שזאת המצוה היא לעקור ע"ז מארץ ישראל:
@9 **את כל המקומות אשר עבדו שם.** מגיד שאנחנו חייבים בארץ ישראל להרוס הבתים שעבדו בהם עבודה זרה ולאבדם כשנבנה הבית לעבודה זרה כמו שיתבאר במה שיבא:
@9 **את אלהיהם על ההרים הרמים ועל הגבעות ותחת כל עץ רענן.** למדנו שאנחנו חייבים לאבד העבודה זרה ששמו באי זה מקום שיהיה בארצינו והנה זכר אלו המקומות כי הם היו נוהגים שישימו שם אלהיהם ולמדנו מזה שאם בטלו אותם הגוי' עבודה זרה ההיא שלא נחוייב לאבדה שאינה אלהיהם בעת שמצאנוה והתורה אמרה את אלהיהם על ההרים שיהיו אלהיהם בעת שמצאנום וכן אמר בפרשת ואתחנן פסילי אלהיהם תשרפון ואמר בזה המקום ופסילי אלהיהם תגדעון ולדנו עוד מזה שאם השתחוו להרים או לגבעות אין אנחנו צריכין לאבדן כי התורה זכרה שאלהיהם על ההרים צונו לאבד ולא ההרים כי לא נקראם המקומות אשר עבדו שם את אלהיהם ולזה גם כן אם עשו מהם עבודה זרה לא נחוייב לאבדם כי אין בהם תפיסת יד אדם כמו שאם השתחוו לשמש או לירח לא תאסר לנו הנאתם ומזה המקום למדנו שהע"ז שהוא תחת עץ רענן לא נחוייב לאבד כי אם הע"ז לא העץ ההוא אחר שאין בו תפיסת יד אדם כמו הענין בהרים ובגבעות אך אם יש בו תפיסת יד אדם כגון שנטעון לע"ז יחוייב לאבדו וזו היא אשרה שחייבה תורה לשרפה:
@10 **ונתצתם את מזבחותם.** רוצה לומר המזבחות שעבדו בהם ע"ז והנה לא צוה לאבדו אלא לנתצו. וזה יהיה כשלא היה בו תפיסת יד אדם לע"ז וחוייבו לנתצו כדי שלא ישאר בו שם מזבח וכן הענין באבן אשר יעשו ממנה מצבה להשתחוות עליה לע"ז כיון שאין בה תפיסת יד אדם לעבודה זרה ישברוה והיא מותרת בהנאה והנה ישברוה לאבד את שמה שלא תקרא מצבה:
@10 **ואשיריהם תשרפון באש.** כבר בארנו שזה יהיה באין שנטעו תחלה לע"ז שיש בה תפיסת יד אדם בכולו:
@10 **ופסילי אלהיהם תגדעון.** זה יהיה באילן שלא נטעון תחלה לע"ז ועשה בה מעשה ע"ז כאלו תאמר שגדעו ופסלו לע"ז הנה מה שצמח אחר זה או מה שיהיה בו תפיסת יד אדם לעבודה זרה אסור ולזה מגדע אותו והשאר מותר ואולם בפרשת ואתחנן אמר פסילי אלהיהם תשרפון באש וזה אמנם יהיה בפסל שנפסל כולו לע"ז כמו שחצב אבן לע"ז:
@10 **ואבדתם את שמם מן המקום ההוא.** זה יהיה בבית שעבדו בו ע"ז ולא היה בו תפיסת יד אדם לעבודה זרה שכבר היה בנוי לא לשם ע"ז ולזה חודש בו דבר לעבודה זרה הנה יספיק שיאבד זה השם מהמקום ההוא ר"ל שיסירה משם ויעבדה כמו שנתבאר בעבודה זרה שהושמה תחת עץ רענן שהעץ ההוא לא נאסר אך יאבד ע"ז שהושמה תחתיו או יהיה הרצון שישתדלו עכ"פ לאבד שם ע"ז מן המקום ההוא שהוא בו אם היה כתוב שם כמו שנהגו בהרבה מאלו:
@11 **לא תעשון כן ליי' אלהיכם.** הוזהרנו בזה שלא לאבד ולנתץ מה שהוא לשם שמים ולזה יתבאר שהנותץ אבן אחת מהמזבח או מהיכל דרך השחתה עובר בלאו ונכלל בזה גם כן שאם אבד שם מהשמות הקדושים עובר בלאו שנאמר ואבדתם את שמם וגומ' לא תעשו כן ליי' אלהיכם:
@12 **כי אם אל המקום אשר יבחר יי' אלהיכם מכל שבטיכם וגומ'.** לא תעשון כן ליי' אלהיכם כמו שהיו עושים הגוים לעבוד אלהיהם במקומות רבים כאמרו אבד תאבדון את כל המקומות אשר עבדו שם הגוים כי אתה לא תעבדוהו כ"א במקום מיוחד והוא המקום אשר יבחר יי' אלהיכם מכל השבטים שם לבד תהיה זאת העבודה לה להעיר על ייחוד הנעבד בה ולזה היה במקום מיוחד ועל יד משפחה מיוחדת והנה אמר מכל שבטיכם לפי שמקו' בית המקדש קנוהו כל השבטים כמו שנתבאר במה שנזכר בסוף שמואל שכבר קנה דוד את גורן הארונה ואת הבקר בכסף חמשים ובמקום אחר אמר שקנהו שש מאות שקלים להורות שמכל אחד מהשבטים לקח חמשים שקלים ואמנם ירושלם היה מאחד השבטים כמו שנתבאר בספר יהושע. ולזה אמ' אחר זה במקום אשר יבחר יי' באחד שבטיך לשום שמו שם ר"ל השרות שכינתו שם ויהיה הרצון בזה שישים שמו שם לשכנו או ירצה בזה מענין ברכת כהני' שנא' שם ושמו את שמי על בני ישר' ולזה אמר אחר זה לשכנו ר"ל להשרו' שכינתו שם ואע"פ שברכת כהנים נאמרת בכל מקום שנא' בכל מקום אשר אזכיר את שמי אבא אליך וברכתיך הנה נלמד מזה ששם המפורש לא יהיה נזכר על יד הכהנים כי אם בבית המקדש לזה אמר לשום את שמו שם אך בשאר המקומות יזכרוהו בכינוי ולזה אמ' אשר אזכיר את שמי שהוא מעניין אזכרה כמו שביאר' שם ר"ל שאריח שמי שם אך לא יהיה נזכר שם בכתבו כמו ריח הדבר שאינו הדבר בעל הריח:
@12 **ובאת שמה.** כבר נתבאר במה שקדם ששלש פעמים בשנה יחוייב להם לבא שמה:
@13 **והבאתם שמה עולותיכם וגומ'.** לפי שסמך זה אל אמרו ובאת שמה למדנו מזה שברגל הראשון שיבא שם יחוייב להביא שם קרבנותיו ונדריו שנא' ובאת שמה והבאת' שמה עולותיכ' הם של יחיד או של צבור:
@13 **זבחיכם.** הם זבחי שלמי צבור או זבחי שלמי יחיד:
@13 **מעשרותיכם.** הם של יחיד. והם שני מעשרות שהם נאכלים שם לבעלים אחד מעשר שני מדגן תירוש ויצהר ואחד מעשר בהמה הנזכרת בסוף פרש' אם בחוקותי:
@13 **ותרומת ידיכם.** אלו בכורים שהיו ישר' מחוייבים להביאם שם בידיהם כמו שנזכר בפרש' והיה כי תבא ולקח ההן הטנא מידך:
@13 **נדריכם ונדבותיכם.** זו עולה הבאה בנדר ונדבה או שלמים כי אלו באים בנדר ונדבה כמו שנזכר בפר' אמור אל כהנים:
@13 **ובכורות בקרבם וצאנכם.** הוא פטר רחם שהוא לכהנים והם יקריבו לש"י אמוריהם והשאר נאכל לכהנים והנה לא זכר חטאות ואשמות לפי שכבר נתבאר בהם שמקו' שחיטתם הוא מקו' שחיטת העולה עם שהדברים ק"ו שאם לא הותר להקריב קדשים קלים כי אם בזה המקו כל שכן קדשי הקדשים:
@14 **ואכלתם שם לפני יי' אלהיכם.** ר"ל במקום אשר יבחר יי' יאכלו הנאכל מכל אלו שזכר ואולי לזאת הסבה שתק חטאות ואשמות לפי שכבר נתבאר בהם שמקום שחיטתן הוא מקום שחיטת העולה עם הדברים ק"ו לקצר המאמר בזה המקום כי אותם אינם נאכלים כי אם לפני' מן הקלעי' ואלו שזכר פה נאכלים לפני' מן העיר:
@14 **ושמחתם בכל משלח ידכם וגומ'.** ר"ל בכל מה שתוכלו לשלח ידכם לעשות ממנו שלמי שמחה במועדי' כשתבואו בבית הבחירה לראו' פני הש"י תשמחו שם אתם ונשיכם ואחשוב כי לנשי' מצות ראיה רשות:
@14 **אשר ברכך יי' אלהיך.** הנה אלו השלמים הם לפי הברכה אש ברך אותך ש"י כי העשיר מרבה בשלמים אלו:
@15 **לא תעשון ככל אשר אנחנו עושים פה היום וגו'.** אמר זה לפי מה שאחשוב שכבר הותרו הבמות לישראל בזולת עולה ושלמי' כמו שנזכר בפר' אחרי מות ולזה היה יכול להקריבם זר כי לא נמנע מזר אלא מלקריב אל משכן יי' ולא היה אסור הקרבת עולה ושלמי' בבמת יחיד כי אם במדנ' לסבה בעינה שנאסרה שם בשר תאוה כמו שבארנו במה שקדם אמנם אחר זה שהותר בשר תאוה הותרו אלו לעשות בבמה יחיד ולזה מצאנו בשאול שהקריב את העולה בבמת יחיד וכן מצאנו בדוד ואל גנו אותם הנביאים שהיו שם על זה ומזה נלמוד גם כן כי ליחיד הותר במת יחיד לא לצבור שנא' איש כל הישר בעיניו ולזה מצאנו שהמקריבי' בבמת יחיד היו יחידים:
@16 **כי לא באתם עד עתה אל המנוחה ואל הנחלה.** מגיד שכיון שבאו אל המנוחה נאסרו הבמות ואחר כך הותרו עד היותם אל הנחלה כי לא נאסרו כי אם כאשר באו אל המנוחה ואל הנחלה. והנה המחונה היה משכן שלה והנחלה היה בית המקדש שהיה בירושלם ואחריו נאסרו הבמות מכל וכל:
@18 **וכל מבחר נדריכם אשר תדרו ליי'.** אחשוב שרמז בזה אל הבהמות שאין בהם מום שנדר אותם ליי' והנה כל זה המאמר זולתי מעט שקצר בו כאלו העיר שכבר יהיו שם שני מקומו' אשר יבחר ה' והם המנוחה והנחלה שזכר תחלה:
@19 **ושמחתם לפי יי' אלהיכם וגו'.** אלו שלמי שמחה:
@19 **והלוי אשר בשעריך כי אין לו חלק ונחלה עמך.** מגיד שאם יש בידו מעשר ראשון שהוא חלק לוי נתנו לו. ואם לא נותן לו מן השלמי' או ממעשר עני:
@20 **השמר לך פן תעלה עולותיך בכל מקום.** ה"ה לשאר הקרבנות אך כתוב קצר ויורה על זה מה שאמר בפסוק אחר זה כי אם במקום אשר יבחר ה' אלהיך באחד שבטך שם תעלה עולותיך וגו' ושם תעשה כל אשר אנכי מצוך. רוצה לומר שאר הקרבנות שחייב קודם זה להביא במקום ולזה יחוייב שיהיו כלם בלא תעשה:
@22 **רק בכל אות נפשך תזבח ואכלת בשר.** ראוי שתדע שאי אפשר שתהיה הכונה בזה להתיר בשר תאוה שנאסר במדבר שהרי זכר אחר זה ענין התר בשר תאוה בפרשת כי ירחיב יי' אלהיך את גבולך ואי אפשר שיתיר זה בקרבנות שהרי ביאר שאין לו רשות להביאם כי אם במקום אשר יבחר ה' ובהיות הענין כן הנה לא ישאר אלא שיהיה זה המאמר בפסולי המוקדשין והם אשר יש בהם מום רע כמו שנזכר בבכור בפר' כל הבכור שאם יש בו מום רע והוא מום קבוע לא יזבחנו ליי' ואם שם בשעריך תאכלנו הטמא והטהור יחדו כצבי וכאיל רק את דמו לא תאכל על הארץ תשפכנו כמים כמו שאמר זה בה המקו' ולזה הוא מבואר שזה מהמאמ' הוא בפסולי המוקדין כי כבר נתבא' למעלה שלא יחוייב הביאם שם כאמרו וכל מבחר נדריכם מגיד שהעי מומין לא יחוייב להביא שם ובהיות הענין כן כבר יתבאר בפר' בחקותי שגם הבהמה הטמאה יחוייב שתפדה בצאתה לחולין למדנו מזה שהוא יחייב באלו שיפדו ואמר תזבח לפי שלא הותר לגדלם אחרי שנפדו כי הם אסורים בגזה ועבודה כמו שהתבאר בפר' כל הבכור:
@22 **ואכלת בשר.** הבשר הותר לו לאכול אך לא יוכל לגדלם ויאכל החלב ואמר ואכלת שלא יותר לו להאכילו לכלבי' כי עדין יש בו קצת קדוש':
@22 **כברכת יי' אלהיך אשר נתן לך.** למד בזה דרך ארץ שיאכל האדם מהבשר לפי עשרו לא יותר וכאלו באר בזה שלא יאסר אם עבר זמנו שהיה ראוי שיאכלנו אם לא היה בו מום ואף על פי שזכר דינו דין קדש לקצת הדברים:
@22 **בכל שעריך.** מגיד שמותר לשחטו ולאכלו בכל המקומות הטמא והטהור יחדו כצבי וכאיל בעבור שלמדנו ממה שאמר תחלה שיש בו עדין קצת קדושה הוצרך לבאר שלא הוזהר הטמא מלאכלו אך טמא וטהור אוכלין בקערה אחת כמו הענין בצבי ואיל שאינן ראויין לקרבן:
@23 **רק הדם לא תאכלנו על הארץ תשפכנו כמי'.** הוצרך לומ' זה לפי שכב' ביאר שיש בו קצת קדושה. אולי יחשוב חושב שדמו יהיה אסור כדם קדשים. לזה ביאר שהוא כמים שמותרים בהנאה ואמ' על הארץ תשפכנו באר שאינו טעון כסוי כדם צבי ואיל:
@24 **לא תוכל לאכול בשעריך וגומ'.** הוזהר בזה שלא לאכל מעשר שני של דגן ותירוש ויצהר חוץ מהמקום אשר יבחר יי' ושלא יאכלו הכהנים הבכורות חוץ מהמקום ההוא ולא השלמים והנה אמר כל נדריך אשר תדור מה שלא אמר כן במה שקדם אך אמר נדריכם וכל מבחר דריכם לכלול העולה עם השלמים כי היא באה בנדר ונדבה כמו השלמים ואי אפשר שנאמר שיכלול בזה פסולי המוקדשין כי כבר הורו לאכול בשערים כמו שקדם ולזה יהיה זאת האזהרה שלא יאכל מבשר העולה באי זה מקום שיהיה כי לא הותר אלא למזבח כאמרו ועשית עולותיך הבשר והדם והנה הדברים קל וחומר אם הדברים שהתר להם במחיצתו נאסר חוץ ממחיצתו לא כל שכן במה שבכל המקומות הם חוץ למחיצתו לאכילת אדם ובכלל הנה נלמד מזה הענין שלא יותר דבר לאכול כי אם בגדרים שהתירה אותם התורה ולפי שלא הותרה העלה כי אם למזבח הנה יהיה מזה אזהרה שלא יאכל אדם מבשרה באי זה מקום שיהיה כי כל מקום יקרא שעריך לזה הענין וכן נלמד מזה שלא יאכל אדם קדשים קודם זריקת הדם כי עדין לא הותרו לאדם ומזה גם כן יתבאר והוא קל וחומר שאסור לאכול קדשים חוץ למחיצתו שהוא לפנים מן הקלעים כי שאר המקומות יקראו שעריך לזה הענין והוא ידוע שהבכורים נאכלין בכל מקם לכהנים ממה שנזכר בפרשת קרח מאכילת הבכורים שלא התנה שם מקום מיוחד לאכילתם ולזה תהיה הכוונה באמרו ותרומת ידך שלא יאכל כהן בכורים בשערים קודם הנחתם בעזרה על האופן שהתבאר בפרשת והיה כי תבא:
@26 **השמר לך פן תעזוב אל הלוי.** הנה זאת אזהרה שלא לעזוב את הלוי שיתן לו חלקו הראוי לו מהמעשרות או ממעשר עני או מהשלמים וממעשר שני שנתחייבו לאכלו בירושלם:
@27 **כי ירחיב יי' אלהיך את גבולך וגומ'.** לפי שלא הותר בשר תאוה במדבר הוצרך להזכיר בזה המקום שבכניסתם לארץ יהיו מותרים בבשר תאוה:
@27 **כי תאוה נפשך לאכול בשר.** מגיד שאין ראוי לאכול בשר אלא לתאבון:
@28 **כי ירחק ממך המקום אשר יבחר יי'.** לפי שהתורה היא אחת לכל אנשי התורה כמו שנתבאר במקומות רבים מהתורה הוא מבואר שאין ראוי שיובן מזה שאשר ירחק מהם המקום יהיו מותרים בבשר תאוה לא הקרובים אל המקום אבל הכוונה בזה שלא יהיה המקום קרוב לכל ישראל מפני הרחבת גבולך ולפי שמפני הרוחק התיר זה הוא מבואר ששחיטת בשר תאוה תהיה חוץ מהמקום אך אם יזבחהו במקום יחוייב שיהיה השלמים ויאכל ממנו המזבח חלקו:
@28 **וזבחת מבקרך ומצאנך כאשר צויתיך.** רוצה לומר שבאופן שצויתיך תהיה זביחת הקדשים והוא בשחיטה כך תהיה זאת השחיטה ואולם אמר זה לפי שהזביחה תאמר גם כן על הנחירה אך גדר השחיטה הוא שתהיה בצואר בחתיכת הסמנים וכבר יתבאר לך שהזביחה תאמר גם כן על הנחירה ממה שאמר ויזבח בלק צאן ובקר וישלח לבלעם ואמר מנקרך להורות שאין ראוי שיאכל אדם בשר אם לא היה לו בקר וצאן רוצה לומ' שיהיה לו די ספוקו לקנותה ואמר מבקרך ולא בקרך שאין ראוי לאדם שיאכל כל אשר לו אך ישער ההוצאה לפי קניינו לפי שימצא לו מזונו תמיד:
@28 **ואכלת בשעריך בכל אות נפשך.** רוצה לומר שזה הנשחט חוץ לעזרה תוכל לאכול בשעריך לא מה שישחט בעזרה כי הוא קדש ומזה המקום למדנו שהנשחט יתכן שתאכל לא מה שלא נשחט:
@29 **אך כאשר יאכל את הצבי ואל האיל.** הזהירנו שלא ינהג בזה מנהג קדש כדי שלא יחשוב שהוא שוחט קדשים בחוץ ולמד בזה שצבי ואיל אינם מורים כי אם בשחיטה וכן הוא אומר כי יצוד ציד חיה או עוף אשר יאכל ושפך את דמו וכסהו בעפר וזה יהיה הרצון באמרו ושפך את דמו שחיטה ומזה המקום נלמד שמצות שחיטה נוהגת בבהמה חיה ועוף והכונה בה מה שיתכן שימותו בו בעלי חיים כף מחתיכת הסמנין וכבר שערו רז"ל שלא יתכן שישלם זה בבהמה וחיה כי אם בחתיכת שני סמנין או רובם אך בעוף ישלם בחתיכת סימן אחד להיות חסר החיות מהבהמה והחיה והוא כמו ממוצע בין הבהמה והדגי' שאינם צריכין שחיטה:
@30 **רק חזק לבלתי אכול הדם.** ביאר בזה שדמה אסור באכילה שלא יחשוב החושב שלא יהיה מוזהר רק על דם הקרבן כדי שיתנו על המזבח:
@30 **ולא תאכל הנפש עם הבשר.** רוצה לומר לא תאכל מה שהנפש בו עדין עם הבשר והוא אבר מן החי רוצה לומר כי עדין יש בנפש כח לשלח באבר ההוא הצריך לו מהמזון לא היה בב"ח:
@31 **לא תאכלנו.** הזהיר עוד על הדם כדי שיהיו יותר נזהרים מאכילתו וכבר זכרנו תועלת זאת האזהרה בפרשת צו:
@31 **על הארץ תשפכנו כמים.** למדנו מזה שאין טעון כסוי ואמ' כמי שלא יכוין בשפיכתו על הארץ לדבר מהדברים שהיו מכוונים בו המכשפים ומה שידמה להם אך יהיה לבו בשפכו אותו על הארץ כאלו שופך שם מים:
@32 **לא תאכלנו למען יטב לך.** הודיע בזה שבהיותם נזהרים מזה יגיע להם ולזרעם תועלת עצום:
@33 **רק קדשיך יהיו לך וגומ'.** צונו בזה להביא כל הקרבנות לבית הבחירה ולזה הוא מבואר שהבעלים מטפלים בהבאתם עד שיהיו שם:
@34 **ועשית עולותיך הבשר והדם.** למדנו בזה שאם אין דם לזרוק על המזבח לא זכה המזבח בבשר וכן אם אין בשר לא יזרוק הדם כי זריקת הדם הוא לרצו' הקרבת הבשר ולמדנו מזה עוד שאף עלפי שמחוייב להקטיר כל העולה למזבח שנאמר והקטיר כהן את הכל המזבחה הנה אם פרשו מהמערכה ופקעו משם הקרנים או הטלפים או העצמות או הגדים אינו זקוק להחזירם שם כי התורה לא דקדקה אלא בשר:
@34 **ודם זבחיך ישפך על מזבח ה' אלהיך ובשר תאכל.** למד על דם כל הזבחים שטעון מתנה אחת ואף על פי שנתבאר בחטאת ועולה שיש בהם יותר ממתנה אחת הנה למדנו מזה שאם לא נתן כי אם מתנה אחת לא עכב:
@34 **והבשר תאכל.** למדנו מזה שאינו זוכה באכילת בשר כי אם אחר שזכה המזבח בהם:
@35 **שמור ושמרת את כל הדברים האלה.** רוצה לומר שישמרם בלב וישמע לעשותם וזה יהיה בלמדנו אותם כי הלמידה מישרת אל המעשה וזכר שמקיום אלו המצות יגיע טוב נפשיי וגופיי לו ולבניו עד עולם כדי שיהיו יותר זריזים בענין אלו המצות. הנה זה ביאור מה שיצטרך אל ביאור בזאת הפרשה שהוגבלה ביאורה פה.
@37 **השמר לך פן תנקש אחריהם.** ר"ל פן תנקש במוקש אשר נוקשו הם וזה יהיה אם תנהג במנהגיהם בעריות ובזולת זה כמו שאמ בפרשת קדושים תהיו ולא תלכו בחקות הגוים אשר אני משלח מפניכם:
@37 **פן תדרוש לאלהיהם.** מגיד שאם ילכו במנהגיהם הפחותים סופם לעבוד ע"ז או ירצה בזה שמא תחקור איך היו עובדי' הגוי' עבודה זרה ותחשוב לעבוד הש' יתע' בדרך ההוא והזהיר שלא יעש' כן ליי' כי מה שיחשבוהו עבודה לו יהיה ההפך כי הם היו עושים לאלהיהם כל הדברים המרוחקים והמתועבים לשם יתעלה כי עד שגם בניהם ובנותיהם היו שורפים באש לאלהיהם אולם כונת התורה הוא בהפך זה שלא העמיסה עלינו דבר יכבד עלינו אבל הם דברי ישרים וצדיקים מישרים בעצמותם אל כל הטובות:
@39 **את כל הדבר אשר אנכי מצוה אתכם אותו תשמרו לעשות.** רוצה לומר על האופן אשר צויתי בו:
@39 **לא תוסיף עליו ולא תגרע ממנו.** כבר ביארנו דיני ההוספה והגרעון שהוזהרנו מהם בראש פרש' ואתחנן:
@40 **כי יקום בקרבך נביא או חולם חלום.** ידמה שקרא הנביא למי אשר יתודע אליו שם יתעלה במראה ואשר ידבר בו בחלום קרא חולם חלום:
@40 **ונתן אליך אות או מופת.** ר"ל כדי שיאמינו בדבריו ובא האות והמופת כמו שיעד אותו קודם באו ויאמר נלכה ונעבדה אלהים אחרים אשר לאי דעתם ונעדם ואל זה נתן לך האות והמופת כדי שתאמין לדבריו:
@42 **לא תשמע אל דברי הנביא ההוא או אל חולם החלום ההוא.** הזהיר בכאן שלא לשמוע אל דבריו כשיאמר לעבוד עבודה זרה גם אמר זה לפי שעה ואף על פי שהתבנא בשם השם יתעלה ויאמר שהשם יתעלה צוה לעשות כך כ"ש אם נתנבא בשם עבודה זרה:
@42 **כי מנסה ה' אלהיכם אתכם וגו'.** הרצון בזה שלזה הסכים שיבא זה המטעה לבם כמו שמצאנו בספר יהושע שהשאיר השם יתעלה קצת הגוים ההם לנסות בם את ישראל והנה האות והמופת שיעד בו הנביא שקר ההוא אינו ראיה בבאו שיהיה אמת מה שאמר כי היה זה בלתי ספק על דרך להט וכשוף ומה שידמה להם והעניין ידוע שאין דבריו אמת כי אין שם אלוה זולתי השם יתעלה כמו שנתברר לישראל במעמד הר סיני הנפלא מפי הגבורה ונתברר עוד מצד העיון במה שאין ספק באמתתו ולזה אין דרך לנתינת אות או מופת להביא להאמין ההפך בזה והוא מבואר שמי שישתדל לאהוב השם יתע' בכל לבבו ובכל נפשו ינצל מההאמנה דבריו והוא מי שישתדל להשיגו כפי כחו כי הוא ישער במה שהשיג ממנו שאין אלוה זולתו:
@43 **אחרי ה' אלהיכם תלכו.** צוה שילכו אחרי השם יתעלה ר"ל שילכו בדרכיו בחקרם איך מנהגו במה שישפע ממנו וזה יהיה סבה שייראו ממנו ויראתם ממנו תסבב שישמרו מצותיו וישמעו בקולו ויעבדוהו לא זולתו וידבקו בעבודתו:
@44 **והנביא ההוא או חולם חלום ההוא יומת.** רוצה לומ' על ידי בית די והוא הקלה שבמיתות בית דין כמו שהתבאר מהשרשים הכוללים:
@44 **ובערת הרע מקרבך.** בער העושה הרעות הגדולות לך פן תכשל ותפול ברע:
@45 **כי יסיתך אחיך בן אמך.** רוצה לומר אחיך או בן אמך שאינו אחיך מן האב והנה דבר הכתוב בהוה שלא יסית איש אחר בזאת ההסתה שיש בה מהסכנה העצומה לו אם יודעו דבריו אם לא יהיה קרבו או רעהו אשר כנפשו ולא יאמרו כמו אלו הדברים לזאת הסבה ג"כ כי אם בסתר:
@46 **הקרובים אליך או הרחוקים ממך מקצה השמים ועד קצה השמים.** הנה הקדים הקרובים כי הם היותר נכונים שיכשלו בהם ואחר כן זכר הרחוקים באי זה המקום שיהיו ממזרח שמש עד מבואו או מקצה הדרום עד קצה הצפון:
@47 **לא תאבה לו.** אפילו שהיה אהובך מצד הקרובה והאהבה כמו שזכר תחלה לא תרצה בו ובאהבתו כי בקש להדיחך ולהאבידך וזאת האזהרה שלא יסכים לדבריו:
@47 **ולא תשמע אליו.** מגיד שאם אבה ושמע חייב אף על פי שעדין לא עבד עבודה זרה וזה יהיה כשצוה לעבוד אלהים אחרים מהקרובים אליו או מהרחוקים אבל אם הסית המסית שיעבדוהו לא ינהג בו זה הדין וזה מבואר מהשרשים הכוללים ולפי שזה המאמר היה בסתר וידענו שאין האדם נדון במיתה כי אם על פי עדים למדנו מזה שיש לנסות להכמין לו עדים שיראוהו וישמעו דבריו והוא לא יראם כדי שיוכלו להעיד:
@47 **לא תחוס עינך עליו.** הותיר בזה שלא לחוס על דם המסית ולא תחמול הזהיר בזה שלא ילמדו עליו זכות:
@47 **ולא תכסה עליו.** הזהיר בזה שלא ישתוק אם ידע לו חובה:
@48 **כי הרג תהרגנו.** צוה בזה להמיתו ושהמוסת תהיה בו ידו בראשונה להמיתו ויד כל העם אחרונה ולפי שזאת ההמתה היא בסקילה למדנו שהמוסה חייב להשליך בו אבן שיהיה בו כדי להמית שנאמר להמיתו ואם לא מת ישליכו עליו כל העם אבנים באחרונה והנה כונה התורה בזה לפייס המוסת שיקח נקמתו מזה שהשתדל להאבידו עם שהוא במדרגת העם בזה והתורה אמרה יד העדים תהיה בו בראשונה להמיתו ולא יוסיפו לעשות כדבר הרע הזה בקרבך זו אזהרה למסית ולפי שאמר כדבר הרע הזה ולא אמר הדבר הרע הזה למדנו שאם הסית שיעבדוהו נהרג כיון שבא לידו מעשה שנאמר ולא יוסיפו לעשות והוא מבואר שאף על פי שלא אמר נלך ועבוד ואמר המסית אלך ואעבוד או אמר אלך ואשתחוה ומה שידמה לזה הרי הוא נסקל שנאמר כדבר הרע הזה וראוי שתדע שאם הסית יותר מאחד דינו גם כן כך אלא אם הסית רוב אנשי העיר שאז נקרא מדיח וכבר נתבאר דינו במה שנמשך לזה והנה אם הסית לשנים או יותר הרי הם עדיו וכדי שיכירו אם הוא שוגג או מזיד יראו אם יוכלו להחזירו לטוב ויאמרו לו היאך אתה אומר זה ואיך יתכן שנניח עבודת השם יתע' שהוא אלהים חיים ומלך עולם והלכנו לנוע על העצים והעל האבנים ואם לא חזר בו מביאים אותו לבית דין וסוקלין אותו:
@51 **כי תשמע באחת שעריך אשר יי' אלהיך נותן לך לשבת שם.** יצא ירושלם שלא נתנה לשבת כי לא נהגה לבית דירה אך היו ישראל עולים שם לרגל ולזה הסכימו קצת רבותינו שירושלם לא נתחלקה לשבטים כי היתה כמו משותפת לכל ישראל וכן הענין לערי המקלט כי לא נתנו לדירה אלא למקלט ולפי שאמר באחד שעריך למדנו שאין עושין בעירות רבות זו בצד זו זה הדין:
@52 **יצאו אנשים בני בליעל מקרבך וידיחו את כל יושבי עירם.** הנה התנאי שיהיו מאותו השבט שנאמר מקרבך ושיהיו מאנשי העיר ההיא שנאמ' את יושבי עירם ושיהיו שנים או יותר שנ' יצאו אנשים ולזה יחוייב שלא יהיו המדיחים נשים או קטנים שנאמר אנשים והתנאי עוד שיאמרו להם נלך ונעבוד באיזו שתהיה ממיני העבודות או נלך ונקבלה באלוה כי זה נכנס תחת גדר העבודה ולפי שנאמר וידיחו את יושבי עירם למדנו שהתנאי בזה שיודחו כל יושבי העיר או רובם והנה יתבאר מצד הוראת הגדר שמי שעמד בעיר שלשים יום יקרא מיושבי העיר:
@53 **ודרשת ושאלת וחקרת היטב.** צוה בזה להרבות בחקירות ובדרישות עם העדים ולשאול היטב כל הדברים אשר יעמידום על הבחינה אם עדותם נכון כדי לעמוד על אמתת הענין:
@53 **והנה אמת נכון הדבר.** רוצה לומ' שאחר החקירות והדרישות והבדיקות נתבאר שהענין כן הוא שנעשתה התועבה הזאת בישראל:
@54 **הכה תכה את כל יושבי העיר ההיא לפי חרב.** מפני שאמר העיר סתם הנה הוא מואר שאינה קטנה שהקטנה תקרא עיר קטנה ולא עיר גדולה כי היא תקרא עיר גדולה וביארו חכמים שלזה הענין תקרא עיר סתם ממאה ועד רובו של שבט אך רובו של שבט אין ראוי לשפוט בזה דין עיר הנדחת כי הוא כמו שבט אחד ואין ראוי שיסבבו שיפקד שבט אחד מישראל וידמה שפחות ממאה לא יתכן שיקרא עיר סתם אך הוא כפר או תקרא עיר קטנה או בת העיר אשר אצלה ואולם הגדולה יתכן שתקרא עיר סתם והנה נמנע השפטם שם בדין עיר כשיהיו רובו של שבט לסבה שאמרנו כי הוא כמו שבט אחד לפי משפטי התורה ואין ראוי להשמיד שבט אחד ולזה ידונו העובדים בסקילה וישאר הטף והנשים וראוי שתדע שזה המשפט לא יהיה ע"י סנהדרי קטנה כי כבר ביארה התורה כי לא ישפטו כי אם יחידים ע"פ סנהדרי קטנה שנאמר והבאת את האיש הוא או את האשה ההיא אל שעריך. למדנו מזה שיחידים נהרגים ע"פ ב"ד שבכל שער ושער אך המרובים אינם נהרגי' אלא על פי בית דין הגדול ולזה תעשה הדרישה והחקירה על פי בית דין הגדול. ואחד כשידעו האמת שיודחו רב יושבי העיר שולחים שם חכמים להחזירם למוטב ולהזהירם שלא יעשו כן כמו שמצינו בנביאים שהיו מוכיחים ישראל כשהיו עובדים עבודה זרה ואם חזרו בתשובה מוטב כי התורה אמר את יושבי העיר ההיא והם עתה אחרים כי כבר שבו מדרכם הרעה עם שהוא ראוי שתהיה שם התראה בהשפטם למות ואם לא חזרו בתשובה מצוים הבית דין הגדול לישראל לבא עליהם לצבא להחרים העיר בזה האופן וזה שהם מרבים שם בתי דינין לחקור מי שעבר אחר התראה בעדים באופן ראוי ואם נמצאו העובדים רובה של עיר דנין אותם כעיר הנדחת ואם לא הרי הן יחידים ונדונים העובדים בסקלה כדין עובד עבודה זרה והשאר פטורין ואם היה רובה של עיר מעלין אותה לבית דין הגדול כדי שיגמרו הדין בפניהם ואחר זה מכין העובדים וטפם ונשיהם לפי חרב שנא' חכה תכה כל יושבי העיר ההיא. וזה כולל כל נפש אדם אשר בה ומצילים הצדיקים אשר בה וטפם ונשיהם רוצה לומר אלו שלא עבדו עבודה זרה אחר ההתראה:
@54 **החרם אותם וגומ'.** למדנו מזה שכל מה שהוא מיושבי העיר ההיא מהנכנסים והמקנה אבד שנא' ואת כל שללה ואת כל בהמתה ואפילו נכסי הצדיקים שבה אבל מה שהיה בה מהאנשים שאינם מיושבי העיר או של הקדש אינו אבד שאין אני קורא בו בהמתה ושללה ומזה המקום נלמד שנכסי הרשעים שבהם שהיו חוצה לה אינו מחוייב שישרף לפי שאינו שלל העיר ההיא ואינו בה והתורה אמרה ואת כל אשר בה אך אם נקבצו שם הרי הם נשרפים שהרי הם שללה ולמדנו מזה גם כן שאין מאבדין מהקנינים בשרפה אלא דבר שיתכן שיקרא שללה והוא דבר המטלטל שאינו חסר אלא קבוץ ושרפה ולזה יתבאר שהפירות המחוברי' לקרקע אינם נשרפי' כי הם חסרין תלישה וקבוץ ושרפה וכן הענין במה שידמה לזה:
@55 **ואת כל שללה.** לפי שראוי לבער הרע מקרבנו כשהיה בזה האופן המגונה בתכלית הנה ראוי שלא נשפוט שיהיה אמרו אל תוך רחובה תנאי שאם לא היה לה רחוב לא נשפוט אותה כעיר הנדחת ועוד שהרי אמרה תורה ושרפת באש את העיר ואת כל שללה מכל מקום ולזה הוא מבואר שכונת התורה בקבוץ שללה לתוך רחובה להוסיף פרסום בענין כדי שיוסרו הנשארי' ולזה הוא מבואר שאם לא היה לה רחוב עושין לה רחוב והרי אני קורא בה רחובה ואם יש לה רחוב חוצה לה עושין בדרך שיהיה רחובה רוצה לומר שיבנו בה חומה סביב העיר באופן שיהיה הרחוב תוך החומה ואז יקרא רחובה ויקבצו שם את כל שלל העיר:
@55 **ושרפת באש את העיר ואת כל שללה כליל ליי' אלהיך.** זהו מצות עשה ואמר שזה הפעל ראוי שיעשה ליי'. רוצה לומר שיכון בעשייתו נתינת האלהות לשם יתעלה במה שיחרים ויאבד עובדי עבודה זרה וכל אשר בה והיתה תל לעולם לא תבנה עוד למדנו מזה שאסור לבנות עיר הנדחת לעולם ולפי שלא הזהיר אלא שלא תבנה למדנו מזה שעושה אותה שדות וכרמים גנות ופרדסים:
@56 **ולא ידבק בידך מאומה מן החרם.** הזהיר בזה שלא ליהנות מממון עיר הנדחת ולפי שעבודה זרה ומשמשיה ותקרובת עבודה זרה הכל נקרא חרם כמו שאמר בפרשת ואתחנן למדנו מזה שהנהנה מעבודה זרה ומכל מה שיעשה בשבילה עובר משום לא ידבק בידך מאומה מן החרם:
@56 **למען ישוב יי' מחרון אפו וגומר.** ביאר בזה שהעושה זה הדין בעיר הנדחת משיב חרון אף יי' מישראל ומביא עליהם רחמים זהו דין עיר הנדחת ואולם מדיחיה יתבאר שדם בסקילה ממה שנאמר במסית ולא יוסיפו לעשות כדבר הרע הזה כי זהו דומה לדבר הו' ויש בו מעשה שהרי הודחו יושבי עירם בסבתם ועבדו עבודה זרה לא היו שם מדיחים או שלא היה שם אלא מדיח אחד או שהיו המדיחים מעיר אחרת או משבט אחר או שהיו המדיחים קטנים או נשי' או שהיתה העיר עיר מקלט או עיר שאינה לדירה ולשבת שם או שהיתה כפר קטן או שהיה בה רובה של שבט או שלא הודחה רובה של עיר הרי כל העובדים נדונים כיחידים בסקילה וממונם ליורשיהם וכבר אמרו רבותינו שאין עושין עיר הנדחת סמוכה לספר כי היא היתה משמרת לשאר ערי ישראל שלא יבואו גוים ויחריבו את ארץ ישראל והנה יתבאר זה לפי מה שאחשוב מצד מה שדקדקה התורה שלא יוזקו בה רק יושבי העיר היא ובהמתה ושללה ואולם בעיר הסמוכה לספר יוזקו שאר העיירות:
@58 **בנים אתם ליי' אלהיכם.** ולזה הוא משגיח בכם כהשגחת האב על הבנים:
@58 **לא תתגודדו.** הוא מענין חתיכה כטעם גודו אילנה והכונה בזה שכומרי עבודה זרה היו נוהגים לחבול בעצמם שהיו חותכים בשרם עד שפוך דם עליהם והנה ההתגודדות לא יהיה אלא בכלי חותך הבשר ומזה הזהירה התורה בזה המקום וזה מבואר מצד הסמיכות וכאלו אמר שהשם יתעלה אוהב אתכם ולזה לא יעמיס עליכם דבר יקשה עליכם אבל ישתדל לשמור אתכם מזה ולזה הזהיר אתכם מההתגודדות שלא תחבלו בעצמכם וכבר מצאנו יתגודדו מענין אגדות וחבורות אמר ובית זונה יתגודדו. וכבר הבינוהו קצת מרבותינו מזאת הכונה השנית והוציאוהו מזה הזהירה התורה בזה המקום וזה מבואר מצד הסמיכות וכאלו אמר שהשם יתעל אוהב אתכם ולזה לא יעמיס עליכם דבר יקשה עליכם אבל ישתדל לשמור אתכם מזה ולזה הזהיר אתכם מההתגודדות שלא תחבלו בעצמכם וכבר מצאנו יתגודדו מענין אגדות וחבורות אמר ובית זונה יתגודדו. וכבר הבינוהו קצת מרבותינו מזאת הכונה השנית והוציאוהו מזה האזהרה שלא יהו שתי בי דינין יושבים בעיר אחת וינהג זה וחבורתו מנהג אחד והאחר וחבורתו מנהג אחר והנה הנכון לפי הפשט הוא מה שביארנו:
@58 **ולא תשימו קרחה בין עיניכם למת.** רוצה לומר על הראש שיסיר השער משם כדרך שתהיה שם קרחה על המוח ולמדנו שחייב על שאר הראש כבין העינים ממה שאמר לא יקרחה קרחה בראשם והנה שימת הקרחה תהיה אם שימרוט השער בידו או שישים על הראש דבר יסבב שתהיה שם קרחה. והנה ידמה שכן היה דרך עובדי עבודה זרה לעשות זה על מתיהם ולזה הוצרכה התורה להזהיר על זה ואולם שיעור הקרחה יתבאר מדיני הצרעת כי שם נאמר קרחת וכבר נתבאר שעורו שם והוא מבואר שמריטות שתי שערות לא יקרא קרחה:
@60 **לא תאכל כל תועבה.** ידמה שאין הכונה בזה בענין עבודה זרה אשר נקרא תועבה שהרי מנע ממנו כל הקנאה בכללות שנאמר ולא תביא תועבה אל ביתך ואין הכונה בו גם כן קדשים בעלי מם שנקראו תועבה בפרשת שופטים אמר לא תזבח ליי' אלהיך שור ושה אשר יהיה בו מום וגומר. כי תועבה הוא. וזה שכבר נתבאר במה שקדם שהיו נפדין ונאכלין במומן ולזה אמרו רבותינו שהו מפסולי המוקדשין שהטילו בהם מום וקנס הוא שקנסה אוו התורה מפני שבזה הקדשים כדי שיאכלם שלא יותר לפדותן וימותו במומן ואפשר שיהיה הרצון באמרו כל תועבה לא תאכל כל שקץ כי השקץ והתעוב אחים אמר שקץ תשקצנו ותעב תתעבנו כי חרם הוא והנה הזהיר בזה אכילת הבעלי חיים שאמר בהם כי שקץ הם בפרשת ויהי ביום השמיני והם הדגים והעופות שאין להם סימני טהרה. וכל שרץ העוף ההולך על ארבע. וכל השרץ השורץ על הארץ. וזה נאות מאד מצד הלשון ומצד מה שנמשך אליו כאלו יאמר כי מצד אהבת השם יתעלה את ישראל והיותם בנים לו הזהירם מלאכל המאכלים המשוקצים והמתועבים שהם מזיקים לבריאות האדם ולהכנת שכלו כמו שביארנו בפרשת שמיני:
@61 **זאת הבהמה אשר תאכלו.** התבאר מזה שחיה היא בכלל אכילת בהמה והקדים לזכור מיני הבהמה להיות יותר נכבדים והנה זכר בסדור כי היותר נכבד הקדים השור שיותר נכבד מהכבש והכבש יותר נכבד מהעז:
@63 **כל בהמה מפרסת פרסה.** זכר שסימני טהרה הם בבהמה וחיה שתהיה הבהמה מפרסת פרסה ושוסעת שסע שתי פרסות לא שתהיה לה פרסה עגולה:
@63 **ומעלת גרה בבהמה.** רוצה לומר כי בבהמה עצמה הנזכרת שהיא מפרסת פרסה ושוסעת שסע יצטרך עוד סימן אחר והוא שתהיה מעלת גרה וכשיתקבצו אלו הסימנין אותה תאכלו לא זולתה ואף על פי שהיא מעלת גרה או היא מפרסת פרסה שסועה כיון שלא נתקבצו בה אלו הסמנין כמו הגמל והארנבת והשפן והחזיר וקל וחומר לשאר בהמה טמאה שאין בה שום סימן טהרה:
@68 **כל צפור טהורה תאכלו.** רוצה לומר שכל עוף טהור תאכלו ולא פרט מיניו לרבויים וכבר נתבאר מזה שצפור המצורע אשר שולחה על פני השדה אשר היא טהורה כמו שאמ' שני צפורין חיות טהורות היא מותרת באכילה וכבר ביארנו סימני טהרה בפרשת ויהי ביום השמיני והנה הוסיף בעופות הטמאים בזה המקום הדיה ואמרו רבותינו שכבר נכלל זה גם כן במה שנזכר בפרשת שמיני ושם נתבאר שהוא ההולך על ארבע רגלים:
@77 **כל עוף טהור תאכלו.** ידמה שרמז בזה אל המינים משרץ העוף ההולך על ארבע והוא אשר לו כרעים ממעל לרגליו לנתר בהם והם הארבה והסלעם והחרגול והחגב למיניהם והנה בזה הסדור נזכר זה גם כן בפרשת שמיני:
@78 **לא תאכלו כל נבלה.** היא הבהמה שמתה:
@78 **לגר אשר בשעריך תתננה ואכלה.** הנה גר שער הוא הגר שקבל עליו שלא לעבוד עבודה זרה כי העובד עבודה זרה לא ישב בארצנו כאמרו בפרשת ואלה המשפטים לא ישבו בארצך פן יחטיאו אותך לי. והתורה צותה במקומות רבים לאהוב את הגר ולזה הקדים היותה לגר בנתינתה למכירתה לנכרי והנה לא רצה השם יתעלה שתתן אותה לנכרי לפי שהוא עובד עבודה זרה ולזה לא רצתה שננה אותו מתנת חנם:
@78 **כי עם קדוש אתה לה'.** ולזה ראוי שתקדש עצמך בעניני המאכלים ולא תתגאל במאכלים העם והמגונים:
@78 **לא תבשל גדי בחלב אמו.** כבר ביארנו עניין זאת האזהרה והתועלת המגיע ממנה בפרשת ואל המשפטים ושם ביארנו מה שהגיע מהתועלת מפני ההכפל זאת המצוה בשלשה מקומות מהתורה זהו ביאור מה שנצטרך אל ביאור במה שהגבלנו לבאר פה מזאת הפרשה.
@79 **עשר תעשר אל כל תבואת זרעך.** ידענו שאין הכונה במעשר הנזכר בזה המקום מעשר ראשון שהיה נתן ללוים כי הוא נאכל בכל מקום כמו שנזכר בפרשת קרח וזה המעשר הנזכר בזה המקו' לא היה נאכל כי אם במקום אשר יבחר ה' כמו שזכרנו בזה המקום ולזה הוא מבואר שזה המעשר הוא מעשר שני והוא שהיו מפרישים הבעלים לאכלו במקום אשר יבחר ה' והוא המעשר הנזכר בסוף פרשת אם בחקותי והנה אמר פה את כל תבואת זרעך ובפרשת אם בחקותי אמר וכל מעשר הארץ מזרע הארץ מפרי העץ למדנו מזה שזה המעשר נוהג בזרעים ובפירות האילן והוא מבואר שאינו נוהג אלא בנאכל מהם שנאמר ואכלת לפני ה' אלהיך ואינו נוהג גם כן מן התורה אלא בדבר המתקיים כי לא יתכן בדבר הבלתי מתקיים כמו הירקות שישאנו שם לאכלו והוא מבואר עוד שאינו מחוייב הפרישו עד שתגמר מלאכתו שנאמר ואכלת שאינו מחסור אלא אכילה ועוד שהרי אמרה בזה המעשר מעשר דגנך תירושך ויצהריך שהם דברים שנגמרה מלאכתם לאכילה ולפי שחייבה התורה לעשות את כל תבואת הזרע למדנו שהגיע לחיוב מעשר אסור לו לאכול מהזרעי' והפירות' עד שיעשר:
@79 **כל תבואת זרעך היוצא השדה שנה שנה.** ר"ל כל מה שתכניס מזרעך שיצא מהשדה לזה הוא מבואר שיש לו לזרוע ממנו בשדה קודם שיעשר ואינו מעשר אלא מה שמכניס לביתו ולזה לא ינהג המעשר בלקט שכחה ופאה והדומה להם ולא ראשון שאן אני קורא בו תבואת זרעך אלא אחר שהפריש ממנו חלק הכהנים והלוים וראוי שתדע שאין ראוי שנבין מזה שאם לא היה הזריעה שלו בהיותו בשדה וזה יהיה כשלקחו מאר ונגמרה מלאכתו ביד הלוקח שיהיה פטור מן המעשר וזה שהרי הזרע הוא שלו כיון שקנאו והתורה לא אמר היוצא משדך ועוד שהרי בפרשת בחקותי לא אמר זרעך אבל אמ' מזרע האר מפרי עץ ולא התנה שתהיה הארץ שלו ולא האילן:
@79 **היוצא השדה שנה שנה.** למדנו שבכל שנה חייב לעשר ואינו מעשר מפירות שנה זו על פירות שנה אחרת ומזה המקום התבאר שכן הענין במעשר ראשון כי המעשר שני בא אחריו כמו שביארנו וכן למדנו מזה שאינו מעשר ממין על שאינו מינו כי לא יאמר עשור כי אם בלקיחת החלק העשירי מהדבר ההוא וכן יתבאר מזה שלא יעשר מן התלוש על המחובר או הפך כי אין זה עשור וכן יתבאר שהעשור לא יהיה באומר כי אם במדידה וזה כולו מבואר ולפי שמעשר בהמה היה דינו כדין המעשר שני ולזה סמכו למעשר שני בפרשת בחקותי ואמר בכל אחת מהם שהוא קדש לה' למדנו מזה גם כן שאין מעשרים בה משנה לחברתה ולא צוו להפריש מעשר בהמה כי אם מבקר וצאן לפי שכונת התורה היתה שיעשו ממנה שלים לה לא יופרש כי אם מהמינים הראוי לשלמים ולזה גם כן תמצא במעשר שני שהוא אפשר שיעשו ממנו שלמים כשהיה אפשר זה כמו שיתבאר אחר זה בג"ה:
@80 **ואכלת לפני ה' אלהיך.** מגיד שאין אוכלו שם אלא בשעה שבית הבחירה קיים והעבודה שם כי אז הוא לפני ה' לא בשעה שנחרב הבית ואין העבודה שם:
@80 **מעשר דגנך תירושך ויצהרך.** מגיד שאין מפרישין מעשר שני אלא מדבר שנגמרה מלאכתו לאכילה:
@80 **ובכורות בקרך וצאנך.** זה ממה שירה עוד שאין זה הענין אלא בפני הבית כי הבכור אינו נאכל כי אם בפני הבית דמו ואמוריו הם למזבח כמו שנתבאר בפרשת קרח:
@80 **למען תלמד ליראה את ה' אלהיך כל הימים.** מגיד שתועלת זאת המצוה הוא שילמד האדם בה ליראה את השם יתעלה וזה כי מפני שלא היה נאכל אלא במקום שיבחר השם יתעלה אשר שם ימצאו החכמים שיורו משפטי ה' ליעקב ותורתו לישראל והם הכהנים והלוים המשרתים לפני ה' הנה ימשך להם זה התועלת מפני אם למקום ההוא הנבחר אכול שם זה המעשר עם שענין המעשר בעצמו מישיר אותם ליראת השם יתעלה בהשיגם זה הנמצא העשירי שהוא בעל כל שאר הנמצאות והנה לא יכבד עליהם באם שם ועמדם שם בשלשה רגלים אשר צותה התורה שיבאו שם לפי שיש להם מן המזון מה שלא יותר להם לאכלו אלא במקום בית הבחירה ושם גם כן ירגילו עצמם מפני זה ליראה את השם יתעלה מצד אחד כי כבר ימצא שם מי שיש לו שעור רב מזה המעשר ולא יוכל להתעכב שם עד שיאכלוהו הוא וביתו ולזה ימהר לתת ממנו ללוים ולשאר הצריכים וזה ממה שירגילו לו ויקנה מנהג בעשיית הצדקה ואמר כל הימים להעיר על נצחיות אלו המצות כל זמן שיהיה שם מקום הבחירה ותהיה העבודה שם:
@81 **וכי ירבה ממך הדרך כי לא תוכל שאתו.** מגיד שהוא יכול לפדותו אם מפני רבוי הדרך אם מפני הקושי שיש בנשיאתו אל המקום אשר יבחר ה':
@81 **כי ירחק ממך המקום.** ביאר שזה הקושי יהיה מפני רוחק המקום הנבחר:
@82 **ונתת בכסף.** כבר אמר בפרשת בחקותי שזה הפדיון יהיה אם גאול יגאל איש ממעשרו שיוסיף חמישיתו עליו והנה התבאר שזה הכסף ראוי שיהיה ראוי לקנות בו בקר וצאן ויין ושכר וכל אשר תשאל נפשו וזה לא ישלם כי אם במטבע לא בחתיכת כסף כי לא יוכלו להשתמש בו לקנות מה שירצו כמו הענין במטבע ולפי שאלו הענינים שזכר הם הסבה כשיוכל לחל קדושת המעשר שני על הכסף למדנו מזה שאם נכנס המעשר שני בירושלם אינו יכול לפדותו:
@82 **וצרת הכסף בידך.** למדה התורה שישתדל שלא יאבד כדי שתשלם כונת התורה בזה המעשר:
@83 **בבקר ובצאן.** אמר זה לעשות מהם שלמים שנאמר ושמחת אתה וביתך אך עולות לא יתכן שיעשה מהם כי התורה צותה שיאכלנו במקום בית הבחירה והגיד בזה שאין חשש אף על פי שיאכל מנו המזבח קצת וישארו בידו עורות כי אינם נאכלים ולא יתכן לחללם על כסף כי התורה לא תקנה הפדיון הזה אלאל במעשר שני בעצמו כשלא הגיע למקום הבחירה והיה זה כן לפי שקניית הבקר והצאן הם לכונת האכילה לא לעורות וזה למדנו מזה באמרו ביין ובשכר לא תקפיד התורה אם יקנה היין עם הקנקים:
@83 **ובכל אשר תשאלך נפשך.** לפי שמעשר שני היה מזרע האץ ומפרי עץ והיה הפרט הנזכר בזה המקום דבר שהוא נאכל והוא מגדולי קרקע או ב"ח טהורים למדנו מזה שאין ראוי שיתן הכסף כי אם בדבר שיש בו תועלת לאכילה או לשתייה. והוא עם זה בשר או גדולי קרקע:
@83 **ושמחת אתה וביתך.** מגיד שכבר יתכן לעשות לו מזה השלמי' והם הנקראים שלמי שמחה:
@84 **והלוי אשר בשעריך לא תעזבנו.** כבר ביארנו זאת המצוה במה שקדם מזאת הפרשה:
@85 **מקצה שלש שנים תוציא את כל מעשר תבואתך וגו'.** מגיד שכאשר הפריש מעשר שני שתי שנים שחוייב לאכלו במקום בית הבחירה כמו שקדם הנה שנה השלישית לא יהיה הענין כן רוצה לומר שלא יחוייב להביאו למקום בית הבחירה לאכלו שם אך יניחהו בשעריו רוצה לומר באוצר במקומו ויעשה בו כמו שזכר בסמוך ואמר את כל מעשר להורות שהוא ממתין אל העת שכלו בו המעשרות והוא חג הפסח כי אז נגיעו בכללם התבואות והפירות:
@86 **ובא הלוי כי אין לו חלק ונחלה עמך.** מגיד שאם לא היה לו חלק עמך תן לו מזה המעשר ולמדנו מזה שזה המעשר הוא נתן לעניים וזה יתבאר גם כן מפני שצוה לתת ממנו לגר מפני שסתמו שהוא עני כמו שאמר במתנות עניים לעני ולגר תעזוב אותם ואמר עוד בזה המקום שינתן ליתו' ולאלמנה לפי שסתמן להיות עניים כי אין סומך ידם. וראוי שתדע שהגר הנז' בזה המקום הוא גר צדק ויעיד על זה שכבר סמך אותו ללוי שהוא בן ברית וכן הענין ביתום ואלמנה והענין בעצמו יחייב זה כי כמו אלו המתנות צותה התורה המקומות שינתנו לעניים ולא אמר בנבלה לגר אשר בשעריך תתננה ואכלה אלא מפני שאיננה ראויה לעניי ישראל:
@86 **ואכלו ושבעו.** למדנו מזה שראו שתהיה נתיניה לכל אחד מהם כדי שבעו:
@86 **למען יברכך ה' אלהיך.** ביאר כי בשכר מה שיתן לעניי' מזה יברכהו הש' יתעלה בכל מעשה ידיו כי הוא חנן אותו כדי שיחון העניים כמו שאמר כי בגלל הדבר הזה יברכך ה' אלהיך:
@87 **מקץ שבע שנים תעשה שמטה.** אחר שהזכיר שבשנה השלישית ובשנה השישית משמטה יפריש מעשר עני ביאר בזה המקום מה שיעזוב לעני בשנה השביעית שהוא שנת השמטה והנה הרצון בשמטה שישמט האד' ידיו מפירותיו אשר בנחלתו ויהיו הפקר כמו שביארנו בפר' ואלה המשפטים וכבר ביארנו בזה המקום גם כן שמה שהלוה אדם לחברו מהכסף והפירות ישמט ידו ממנו בזאת השנה שהיה שנת השמטה ולזה אמר שמוט כל בעל משה ידו והוא מבואר שלוה הוא עני ולזה הוצרך ללות:
@88 **לא יגוש את רעהו.** למדנו מזה שאם היה נגוש ועומד קודם השמטה אין השמטה משמטת אותו אך אם לא היה כן הוא מוזהר שלא לתבוע בב"ד החוב שעבר' עליו שביעית והוא מבואר שלא הוצרך להזהירו שלא ינגשהו בשנת השמטה:
@89 **את הנכרי תגוש.** זו מצות עשה כדי שלא נתן מתנות חנם לעובדי עבודה זרה:
@89 **ואשר יהיה לך את אחיך תשמט ידך.** זו היא מצות עשה רוצה לומר שיפקיר החוב ההוא ויסלק ידו ממנו ולזה הוא מבואר שכבר זכה בו הלוה. אולם החוב שיהיה לו אצל הגר תושב אינו מחוייב לנוגשו ולא לעזבו:
@90 **אפס כי לא יהיה בך אביון.** הבטיחם שלא יהיה בך אביון אם ישמרו מצות השם יתעלה ולא יצטרך אחד מכם ללות מחברו או מגוי כמו שאמר והעבטת גוים רבים ואתה לא תעבוט וראוי שתדע כי כבר יתבאר מאמרו מקץ שבע שני' תעשה שמטה וזה דבר השמטה כי השמטת כספים נוהגת בין בארץ בין בחוצה לארץ בין בפני הבית בין שלא בפניו שאם לא היה הדבר כן לא היה צריך לומר תעשה שמטה וזה דבר השמטה אך הי אומר מקץ שבע שנים בשנת השמטה שהיה משמט בה קרקע כמו שנתבאר בפרשת ואלה המשפטים. ואמנם אמר תעשה שמטה שאף על פי שאינה שמטה מדרך אחרת תעשהו שמטה לזה הענין:
@93 **כי יהיה בך אביון מאחד אחיך.** ידענו שהתורה צותה בכללות לחון העניים מישראל איך זה שיהיו אך זכר אלו התנאים להודיע אי זה עני הוא וקדם ולזה אמר מאחד אחיך שהם קרובים כי הם קודמים לשאר עניים שאינם ממשפחתו:
@93 **באחד שעריך.** רוצה לומר שיהיה האביון באחד שעריך אף על פי שלא יהיה קרובך כיון שהוא מעירך והוא קודם לשאר העניים שהם מעיר אחרת או ירצה באמרו באחד שעריך שהוא מאחד מערי שבטיך כי עניי שבטו קודמין לשאר העניים:
@93 **בארצך.** רוצה לומר שיהיה האביון בארצך והוא קודם לעניי חוצה לארץ ולזה אמר גם כן בסוף הפרשה זאת ההדרגה בעינה והוא באמרו לאחיך לענייך ולאביונך בארצך ביאר שאחיו אם הוא עני קודם לעניי עירו ועניי עירו קודמין לענני עיר אחר' מארץ ישראל ועניי ארץ ישראל קודמים לעניי חוצה לארץ:
@93 **לא תאמץ את לבבך.** רוצה לומר להמנע מלרחם עליו:
@93 **ולא תקפוץ את ידך.** אך תפתחה לקחת בה דבר לתת לו:
@94 **פתוח תפתח את ידך לו.** רוצה לומר לתת לו על דרך החמלה והצדקה:
@94 **והעבט תעביטנו.** מגיד שאם יש לו משכון תלוהו על המשכון ותנהג במשכון לפי מה שחייבה התורה במשכון העני לפי מה שנזכר בפרשת ואלה המשפטים:
@94 **די מחסורו אשר יחסר לו.** למדנו שמחסורו הוא עליך. אף על פי שאין לו משכון ואמנם זכר המשכון להודיע שההלואה קודמת למתנה עם שלא יושג בה בשת לעני והנה לא זכר בכאן שיתן לעני בקש די מחסרו להודיע שאף על פי שלא ישאל חייב אתה לפרנסו ואין ראוי שנדמה שכל אחד מהאנשים אשר בעיר יחוייב לתת לו די מחסורו או שיהיה החיוב על הראשון שיבוא אליו העני אבל ראוי שבין בני העיר ישלם זה לעני ולזה הוא מבואר כי צריך שיהיה בעיר ממונה על הצדקה או ממונים והנה אמרו די מחסורו אשר יחסר לו כולל כל מה שיחסר לו ממזון וכסות ואפילו עבד לשמשו ואפילו סוס לרכוב עליו ואמר אשר יחסר לו להעיר שלפי מנהגו וענינו יותן לו המצטרך אליו שאם היה רגיל בפת חטים לא נאכילהו שעורים ואם היה לבוש בגדים חדשים לא נלבישהו שחוקות:
@95 **השמר לך פן יהיה דבר עם לבבך בליעל.** הזהיר בכאן שלא ימנע מלהלוות לעני מפני ראותו שקרבה שנת השמטה ויזכה אז העני במלוה ההוא:
@95 **וקרא עליך אל ה'.** ר"ל שהעני יצעק אל השם יתע' והוא ישמע צעקתו כמו שאמר ביתום ואלמנה כי אם צעוק יצעק אלי ושמעתי כי חנון אני ויהיה הכונה באמרו והיה בך חטא והיה בך עונש כי חטא ועון יאמרו לפעמים על עונש או קצר הכתוב בזה ואמר והיה בך חטא להודיע שאיך שיהיה הנה יהיה בך חטא מפני שלא נתת לאביון ההו' המצטרך לו ואף על פי שלא יקרא עליך אל ה':
@96 **נתון תתן לו.** זו היא מצו' עשה:
@97 **כי לא יחדל אביון מקרב הארץ.** יאמר זה להודיע שגלגל הוא שחוזר בעולם ואם הוא נותן עתה לעני לזמן אחר יעשיר העני ויתן לו או לאחד מזרעו ואולם מה שאמר למעלה אפס כי לא יהיה בך אביון אינו יעוד שלא יהיה בו אביון אך הודיע שאם ישמרו כלם דרכי השם יתעלה ומצותיו לא יהיה בהם אביון וזה שאף על פי שהו' אמת הנה הוא רחוק שיקרה זה שיהיו העם כלם צדיקי' בזה האופן ולזה אמר על דרך היעוד הנבואיי כי לא יחדל אביה מקרב הארץ:
@98 **כי ימכר לך אחיך העברי או העבריה ועבדך שש שנים.** בעבור שזכר עתה דבר השמטת הכספים שהוא בשנת השמטה לכספים ואף על פי שאינה שמטה לקרקע בא לזכור עתה דבר החירות אשר יהיה בשנה השביעית במכירתו לעבד עברי ולפי שזכר דבר עבד עברי זכר עמו דבר אמה העבריה להדמות אשר ביניהם בענין הענקה אשר נתחדש דינם בזה המקום ואמר כי ימכר לך אחיך העברי להעיר על הנמכר בגנבתו שימכרוהו בית דין וכבר נתבאר דינו בשלמות בפרשת ואלה המשפטים היא אשר ימכור אותה אביה לאמה בעודה קטנה כאמרו וכי ימכור איש את בתו לאמה:
@98 **ועבדך שש שנים.** שב לעבד עברי כי האמה העבריה לא תמכר ליותר מהזמן שהיא ברשות אביה כמו שביארנו שם ולזה יתכן שיהיה זה הזמן פחות משש שנים או יותר:
@99 **לא תשלחנו ריקם.** הוא מצות לא תעשה:
@100 **הענק תעניק לו מצאנך ומגרנך ומיקבך.** מפני שאמ' לא תשלחנו למדנו שכיון שלא ישלחהו ריקם יצא ואולם הודיע בזה המקום כי לפי עושר בעל הבית יהיה שעור זאת ההענקה:
@101 **וזכרת כי עבד היית במצרי ויפדך ה' אלהיך.** הנה כמו שהוציאך אז השם יתעלה חפשי והעניק אותך שם במה שנשאתם ממצרים כלי כסף וכלי זהב ושמלות כן אנכי מצוך להוציא העבד עברי חפשי אחר שש שנים ולהעניק לו מאשר ברכך ה' אלהיך:
@102 **והיה כי יאמר אליך.** כבר ביארנו דין זאת הרציעה ותנאיה בפרשת משפטים:
@103 **ואף לאמתך תעשה כן.** רוצה לומר בדבר ההענקה:
@104 **כי משנה שכר שכיר עבדך שש שנים.** אמר זה לפי שהוא עובד ביום ובלילה ולזה היה הרשות ביד רבו למסור לו שפחה כנענית ואפשר שיהיה הרצון בזה כי ימי השכיר הם ג' שנים כאמר' שלש שני כימי שכיר ולזה יהיה זה שעבד ו' שנים עובד משנה שכר שכיר:
@104 **וברכך ה' אלהיך בכל אשר תעשה.** אמר זה שלא יחשוב שום אדם שהש' יתע' יברכהו והוא יושב ובטל ולא ישתדל בהבאת הברכה לו ולזה אמר בכל אשר תעשה כי השם יתעלה יעשה מה שיעשה בסיבות היותר נאותות כשהיה אפשר בה כמו שזכרנו במקומות רבים מזה הספר:
@105 **כל הבכור אשר יולד.** לפי שצריך להיות פטר רחם אמר יולד כי הלידה הוא דרך הרחם:
@105 **הזכר תקדיש להשם אלהיך.** לפי שכבר נאמר בפרש' בחוקותי אך בכור אשר יבוכר להש' בבהמה לא יקדיש איש ואתו למדנו מזה הענין ההקדשה הזאת אשר חייב בה בזה המקום לבכור הוא זולת ענין ההקדשה אשר הזהיר עליו שם ולזה יהיה ענין ההקדשה הזאת שיאמר בכור זה לה' כדי להוסיף שמירתה שלא ינהגו בו מנהג חולים כי כבר הזהיר עליו שלא לעבוד בו ושלא לגזזו וזאת המצו' תהיה לבעלים בהולדו ברששותם וידמה שהם מטפלים בו זמן מה לגדלו ולהניקו מעט כדי שיהיה ראוי שיתנוהו לכהן כמו שמצאנו בתרומה שלא נתנה לכהן אלא אחר גמר מלאכתה ולזה אחיה אזהרת אמרו ולא תעבוד בבכור שורך לבעלים גם כן כמו שהוא לכהן ולזה אמר שורך צאנך ולזה ביאר בזה המקום שהבכור בין תם ובין בעל מום אסור בגזה ובעבודה שנאמר כל הבכור אשר יולד וגו':
@105 **לא תעבוד בבכור שורך ולא תגוז בכור צאנך.** ואף על פי שנולד במומו לפי שקדושתו מרחם והנה הודיע הכתוב זה הדין בבכור והוא הדין לשאר קדשם ואמנם ביארה התורה זה בקדשים קלים ושתקה מהשאר כי הדברים קל וחומר ובכלל האזהרה הזאת רחל ועז להלכה הנה ביארה התורה שאסור ליהנות בקדשים בזולת האופן אשר הגבילה התורה לזה אמר עבודה בבכור שור וגזה בבכר צאן אלא שדברה התורה בהוה והנה שעור הגזה הוא החלק הראשון מהצמר שיהיה ראוי לדבר כי הגזה היא מלאכה יכוין בה תכלית מן התכליות ואיננה באופן שיגזזו שער אחר שער שנוכל לומר שאם גזזו שתי שערות יהיה חייב:
@106 **לפני ה' אלהיך תאכלנו שנה בשנה.** מגיד שאינו נאכל אלא במקום הבחירה והוא נאכל כל שנתו ואמנם אחר זה לא הסכימה התורה לגדלו עוד שמא יגדלנו הכהן ממנו עדרים ויבא הענין לדבר תקלה מצד הגזה והעבודה ומה שידמ' להם והנה מה שאמ' לפני ה' אלהיך תאכלנו אינו מדבר אלא בתם ולפי שאמר לפני ה' אלהי תאכלנו נמשך למה שאמ כל בכור אשר יולד בבקרך. ובצאנך למדנו שהכהן גם כן יחוייב להפריש בכורות והיה זה כן לפי שקדושתו מרחם ובכלל הה ביארה התורה הפטר מכהנים והלוים מבכור אדם שאינו אלא קדושת דמים ושתקה מהבכור וזה יחוייב שיהיה הכהנים והלוים חייבים בבכור בהמה:
@107 **וכי יהיה בו מום פסח או עור כל מום רע לא תזבחנו לה'.** ידענו שאם היה בו מום אי זה שיהיה לא יתכן לזבחו לה' כמו שנתבאר בפרשת אמור אל הכהנים ואולם אמר בזה המקום פסח או עור כל מום רע לפי שבזולת זה לא יתכן שיאכלנו בשעריו. רוצה לומר אם לא היה בו מום קבוע ואמ' לא תשבחנו לה' לבאר שלא הוסרו ממנו מן הקדושה רק שלא יזבחנו ליי' ושהוא אפשר לאכלו בשעריו אך הוא עובד בסוף שנתו שלא הותר לו לזבחו לה' ולא לאכלו בשעריו הנה יוכל להמתין עד העת שהוא ראוי שיהיה עובר בו אם היה עובר והוא שלישי' יום מעת נפילת המום כי שערו חכמים דבר הבחינה הזאת ואולם תוך שנתו אם נפל בו מום עובר יש לו להמתין יותר משלשים יום תוך שנתו כדי להבחין אם נקבע מומו אם לא:
@108 **בשעריך תאכלנו הטמא והטהור יחדו.** מגיד כי כשנשחט במומו יוכל לאכלו בשעריו ויותר לטמא ולטהור לאכול ממנו בקערה אחת וכבר ביארנו בפרש' בא אל פרעה שבכור בהמה טהורה אינו נוהג אלא באדם לזה לא תנהג הזביחה לה' בבכור בהמה טהורה כי אם בבכורות הבאים מארץ ישראל לא בבכורות הבאים מחוצה לארץ ולפי שמצאנו בבכור שהוא ממון כהן ולא זכה בו מן המזבח שהרי הוא אוכלו במומו בלא פדיון למדנו מזה שבכורות חוצה לארץ הם לכהן כי אין תלוי ענינם בארץ כי אם לזבוח ולזה יהיו נאכלים במומן ולזאת הסבה יתבאר שהבכורות נוהגין בין באץ בין בחוצה לארץ בין בפני הבית בין שלא בפני הבית וכבר יתבאר שהכהן יזכה בבכור בהמה בכל מקום וכל זמן שהרי מצאנו בפטר חמור ובבכור אדם שנוהג בכל מקו' ובכל זמן ולפי שאין זוכה בבכור בהמה טהורה מן המזבח למדנו שדינו כדין שאר הבכורות אלא שלא יזבחו ממנו להשם כי אם כשהיה בארץ ובפני הבית לזה אמר והיה כי יביאך בבכורות בפרשת בא אל פרעה והנה אמר בפרשת כל פטר רחם לכל בשר הנה כלל שלשת אלו המינין יחד לענין היותם ממון כהן אלא שביאר שההבדל ביניהם הוא שבכור בהמה טהורה אינו נפדה ושאר הבכורות נפדין וכבר נבאר זה בג"ה ביאור רחב ולפי שאמר בבכור שורך בבכור צאנך למדנו שאם היה של הקדש או של גוי אינו חיי בבכורה. וכן הענין אם היה להם חלק בה שאין אני קורא בה שורך צאנך:
@110 **שמור את חדש האביב.** מזה המקום למדנו שצריך לעבר קצת שנים כדי שיבא פסח בזמן האביב וכבר זכרנו זה במה שקדם:
@110 **הוציאך ה' אלהיך ממצרים לילה.** אף על פי שביום יצאו כאמרו היום אתם יוצאים בחדש האביב. הנה התחלת הוצאתם היתה בלילה כי בסבת מכת בכורות מהרו לשלחם:
@111 **וזבחת פסח לה' אלהיך צאן ובקר.** הנה הצאן היה לפסח אמנם הבקר היה לחגיגת הפסח והם שלמי חגיגה הבאה עם הפסח כמו שזכרנו במה שקדם:
@111 **במקום אשר יבחר ה' לשכן שמו שם.** צוה זה המקום לזבוח את הפסח בבית הבחירה:
@112 **לא תאכל עליו חמץ שבעת ימים תאכל עליו מצות.** כבר ביארנו במה שקדם שאין אכילת מצה חובה אלא בליל הראשון של פסח. ואולם הכונה היא שמה שיאכל מהלחם כל ז' ימים יהיה מצה לא חמץ ושם ביארנו אלו הדינין הנמשכים לה בשלמות ולא ילין מן הבשר אשר תזבח בערב ביום הראשון לבקר כבר ביארנו במה שקדם האזהרה מלהותיר בשר הפסח. ומלחלין אמורי חגיגת הפסח עד הבקר שנאמר ולא ילין חלב חגי עד בקר ובזה המקום הזהיר מלהותיר מבשר שלמי חגיגת הפסח עד הבקר לא תוכל לזבוח את הפסח באחד שעריך ביאר בזה המקום שהפסח אינו נשחט כי אם בית הבחירה כשהיה שם מקום הבחירה רוצה לומ' שילה ובית העולמים שנאסרו אחריו הבמות:
@115 **שם תזבח את הפסח בערב כבא השמש.** רוצה לומר ששחטו לאכלו בערב כבא השמש ולפי שזביחתו היא שם הוא מבואר שזכה המזבח בדמיו ובחלבו:
@115 **מועד צאתך ממצרים.** רוצה לומר כל הלילה שיצאו בו ממצרים שהיה בו מכת בכורות כי הלילה הוא לבד יוכל לאכלו לא יותר ובשלת ואכלת במקום אשר יבחר ה' אלהיך בו מגיד שבשולו ואכילתו יחוייב שיהיה במקם הבחירה ולפי שזה לא יחוייב להיות בבית הבחירה שנה המאמר בזה להעיר שיש הבדל בין זה המקום ומקום זביחת הפסח כי מקום זביחת הפסח ינהג מנהג שאר הקדים ולזה יחוייב שיהיה נשחט בעזרה:
@116 **ופנית בבקר והלכת לאהליך.** לפי שהזכיר בכאן מה שיעשה מהפסח במקום הבחירה חתם המאמ' איך יהיה הפרדו משם בשובו לביתו ואמר שיפנה לביתו בבקר ללכת ולמדה תורה דרך ארץ שלא יצא אדם לדרך אלא ביום ולמדה ובזה יראה שאין באו שם דומה עליו למשא. ואמר בבקר להעיר על החריצות והזריזו' עם שבזה הערה שאם עמד שם קצת היום אין ראוי שיצא משם ביום ההוא מפני חובת המקום הנכבד ההוא:
@117 ששת ימים תאכל מצות וביום השביעי עצרת. אמ' זה כדי שלא נחשוב שנמנה היום השביעי ליום שחיטת הפסח שהוא י"ד ויהיה היום השביעי לו היום העשרים ולזה אמר שאחר שיעברו ששה ימי' לאכילת מצה יהיה היום השביעי עצרת והוא אסור בעשית מלאכת עבודה כמו שקדם ואולם קצר בזה המקום מלבאר אי זו מלאכה הוא שהזהיר עליה בזה המקום להשענו על מה שנתבאר מזה במה שקדם:
@118 **שבעה שבועות תספור לך מהחל חרמש בקמה תחל.** כבר ביארנו במה שקדם שהתחלת הקצירה ראוי שתהיה קצירת העמר הבא בי"ו בניסן ולזה הוא מבואר שזאת הקצירה דוחה שבת כמו שביארנו בפרשת אמור ועשית חג שבועות לה' אלהיך:
@119 **מסת נדבת ידך אשר תתן.** חייבתהו התורה להביא שלמי חגיגה בי"ט ההוא לפי שלא תשיג ידו להתנדב בזה לפי שמעשרותיו שהביא שם אינם בנדבה שהרי הם חובה עליו להביאם שם ולאכלם שם למדנו שצרך להביא מן החולין כאשר יברכך ה' אלהיך לפי שזה הלשון בעינו מצאנו בענין המעשרות זאת הפרשה באמרו. ושמחתם בכל משלח ידכם אתם וביתכם אשר ברכך ה' אלהיך והיה זה כן לפי שהם יהיו בהכרח לפי הברכה מה שאין כן בנדבה למדנו מזה שכבר יביאה גם כן ממעשרותיו ולזה אמרו רבותי' זכרונ' לברכה שהאכילה ראשונה יביא מן החולין והשאר יביא ממעשר שני כי הוא הוגבל לאכלו שם שלמי חגיגה כמו שקדם ואחר כך יאכל מעשר בהמה שהוגבל גם כן לאכלו שם כמו שקדם:
@120 **ושמחת לפני ה' אלהיך.** חייבו גם כן בשלמי שמחה ואמ' לתת ממנו ללוי כשאין לו לתת מחלקו:
@120 **ולגר וליתום ולאלמנה.** צוה בזה כשיהיו צריכים לזה והיו עניים והנה זכר אלו לפי שסתמן להיותם עניים כמו שזכרנו במה שקדם:
@121 **וזכרת כי עבד היית במצרים ושמרת ועשית וגו'.** בעבור שפסח הוא לזכירה גם כן כי עבד היה ישראל במצרים הנה יתבאר שהחגיגה והשמחה נוהגות בו באון שנתבאר בחג השבועות וכבר נתבאר בחג הסכות זה המקום שחגיגה והשמחה נוהגות בו ויתבאר בזה המקום שהם באות מן החולין והמעשרות באופן שזכרנו בחג השבועות עם שכבר מצאנו בכלם אחר זה שנאמר איש כמתנת ידו כברכת ה' אלהיך אשר נתן לך וזה יורה על שאלו הדברים באין מן החולין ומן המעשרות:
@124 **שבעת ימים תחוג לה' אלהיך.** מגיד שחגיגת חג הסכות יש לו תשלומין כל שבעה. וכן הענין בחגיגת יום ראשו של פסח שהרי הוא ראוי בזה הדין כמו חג הסכות. וכבר נתבאר במה שקדם בפרשת אמור אל הכהנים כי ביום ראשון של פסח תהיה שם חגיגה:
@125 **שלש פעמים בשנה יראה כל זכורך את פני ה' אלהיך.** הכונה בזה שיראה האחד את האחר כטעם נתראה פנים ולפי שראיית ה' הדברי' הוא היותר שלמה שאפשר שצריך שיהיה שם בבא להתראות פניו באופן שתהיה ראייתו שלמה לפי מה שאפשר כי למען ראות פלאות אשר בבית הבחירה הובא שם ללמד מהדברים ההם מה שאפשר לו להשיג מהם מהשלמות. ולזה אמרו שסומא באחד מעיניו פטור מן הראיה כן בראותו חסרון ואולי יביא זה לחשוב שבראית השם ית' הדברים יש חסרון ולהורות על שלמות ראיית השם יתע' הדברים חוייב שיהיה הבא שם רואה בשתי עיניו ולזה גם כן דקדקה התורה שלא יבאו שם כי אם הזכרים להיותם יותר שלמי ראיית הלב:
@125 **כל זכורך.** העיר בו שאפילו קטנים יחוייב שיביאום שם כשיהיו בצד יאות לחנכם בזה כדי שילמדו ליראה את ה' הנכבד:
@125 **בחג המצות ובחג השבועות ובחג הסכות.** הנה דקדקה לפתוח בכל המקומות בחד המצות כי הוא הראשון לכל המועדים ומזה הענין נתישר לעמוד על הכונה שכונה התורה באלו המועדים כמו שהתבאר מדברינו במה שקדם:
@125 **ולא יראו פני רקם.** בכאן הזהיר שלא ימנעו מלהעלות עולה לשם יתעלה בבואם לראות פניו. והנה אמרנו שהכונה היתה בכאן לצות על העולה כי היא לה' שאם היתה הכונה בכאן לזולת זה מהקרבנות שיאכל המזבח מהם חלקו כמו השלמים הנה לא היה צריך לצות על זה שהרי היו שם שלמי חגיגה ושלמי שמחה ולזה הוא מבואר שכונת התורה הוא לצות על העולה והיא נקראת עולת ראיה:
@126 **איש כמתנת ידו כברכת ה' אלהיך אשר נתן לך.** לפי שהעולה אי אפשר שתהיה באה מהמעשרות הוצרך לומר איש כמתנת ידו כי לפי אשר תשיגידו ירבה בעולות או ימעיט וכן הענין במה שהוצרך משלמי חגיגה להביא מהחולין והשאר משלמי חגיגה ושלמי שמחה יהיה שעורו. כברכת השם אלהיך אשר נתן לך. רוצה לומר שלפי רוב ברכתו ירבה באלו השלמים או ימעיט ולפי שאין הכונה בשלמי שמחה אלא לשמוח באכילת בשר וראינו שהוא יוצא מהם ידי חובתו במה שיביא שם מהמעשר שני למדנו שאם אין לו מעשר שני יביא מעשר בהמה או בנדרים ונדבות כמו השלמים. הנה זה ביאור מה שצריך לבאר בזה המקום מענין המועדות ואלם שאר דיניהם התבארו במה שקדם.

@1 **ואולם התועלות המגיעים ממנה הם י"ו:**
@1 **התועלת** הראשון הוא במצות והוא מה שצונו אחר עברם את הירדן לתת ברכה על הר גריזים והקללה על הר עיבל כדי לזרז ישראל יותר בשמירת המצות שם כי זה עם מה שיועיל לאדם תועלת נפשיי ימשך להם מזה מהתועלת בענין ירושת הארץ כמו שקדם ויתבאר יותר בפרשת והיה כי תבא:
@1 **התועלת** השני הוא במצות והוא מה שצונו לעקור ע"ז מארצנו והנה התועלת בזאת המצוה מבואר כדי שלא ישאר זכר לע"ז ויוסר מהאנשים ההכשל בה והנה מני שאנחנו מוזהרים מעבודה זרה בכל המקומות הוא מבואר שראוי שנעשה כן בכל המקום שיהיה לנו ואולם ההבדל בזה בין ארץ ישראל וחוצה לארץ הוא שבארץ ישראל אנחנו מחוייבים לרדוף אחריה ולכלותה כדי שלא תשא ע"ז בארצנו כמו שצונו שלא ישבו בארצנו עובדי ע"ז כאמרו לא ישבו בארצך פן יחטיאו אותך לי אמנם בחוצה לארץ אין אנו מצווים שלא ישבו אתנו עובדי ע"ז וכמו זה אין אנחנו מצווים לרדוף אחר ע"ז שלהם לכלותה אך המקום שיהיה לנו בחוצה לארץ והיתה בו ע"ז הוא מבואר שאנחנו מצווים לכלותה משם:
@1 **התועלת** השלישי הוא במצות והוא מה שהוזהרנו מלנתוץ דבר דרך השחתה מהבנין שנעשה לשם יתעלה כ"ש שאנחנו מוזרים מלאבדו שנאמר ונתצתם את מזבחותם וגומ' לא תעשון כן לה אלהיכם והנה התועלת בזאת המצוה מבואר:
@1 **התועלת** הרביעי הוא במצות והוא מה שהוזהרנו מלאבד שם מהשמות הקדושים אשר לשם יתעלה והוא שנאמר ואבדתם את שמם וגומ' לא תעשון כן לה' אלהיכם והנה התועלת בזאת המצוה מבואר:
@1 **התועלת** החמישי הוא במצות והוא להודיע שלא יתכן שנעבוד השם יתעלה במקומות רבים כמו שעשו הגוים ההם לאלהיהם אך נעבדהו במקום מיוחד לבד והוא המקום אשר יבחר יי' להורות על יחוד השם יתעלה הנעבד בזאת העבוד' הנכבדת עם שמזה ימשך מהתועלת שתהיה זאת העבודה נעשית בבית הנפלא אשר בו הישרה נפלאה להעמיד על סודות המציאות ועל ידי משפחה מיוחדת נכונה לעמוד על אופן החכמה אשר בזאת העבודה מפני שקדת עליה והיותה בלתי צריכה אל אסיפת הקנינים כי לחמה נתן מימיה נאמנים והנה לא תנהג זאת המצוה כי אם אחר המצא שם מקום יבחר יי' שנאמר כי לא באתם עד עתה אל המנוחה ואל הנחלה מגיד שאחר שבאו אל המנוחה ואל הנחלה נאסרה בזה עולמית:
@1 **התועלת** הששי הוא במצות והוא מה שלמדנו מאמרו לשום את שמו שם שברכ' כהנים לא תהיה בשם המפורש אלא בבית המקדש ואף על פי שהיא תהיה בכל מקום כאמרו בכל המקום אשר אזכיר את שמי אבא איך וברכיך והנה התועלת בזאת המצוה מבואר והוא שאין ראוי לגלות ענין זה השם הנכבד רק במקום מיוחד לעבודתו כי מפני זה מצאו שם תמיד משיגים סוד זה השם לפימה שאפשר וזה ממה שישמר השומעים שלא יבאו מזה להריסה מפני השתבשם בענינו כי שם מי שישמרם מהשבוש הזה.
@1 **התועלת** השביעי הוא במצות והוא מה שצונו להביא כל הקרבנות שיש לנו איך שיהיו ברגל הראשון שנבא בו לבית הבחירה שנאמר ובאת שם והבאתם שמה עולותיכם וזבחיכם ומעשרו' וגו'. והתועלת בזאת המצות מבואר כדי שישלים חקו אשר צותה לו התורה מהם וישלם נדרם תכף שימצא לו מקום ראוי:
@1 **התועלת** השמיני הוא במצות והוא מה שהזהירתנו מהקריב קרבנות חוץ מהמקום אשר יבחר יי' והנה נתבאר תועלת זאת האזהרה ממיה שקדם:
@1 **התועלת** התשיעי הוא במצות והוא מה שצוה לפדות פסולי המוקדשים שיש בהם מום קבוע וביאר דיניהם אחר שנפדו שישאר בהם דין קצת הקדשים והתועלת בזאת המצוה הוא שלא להפסיד הקדשים אחר שאינם ראויים להקרבה ולזה צוה שיצאו לחולין בזה האופן שזכר באמרו שם תזבח ואכלת בשר:
@1 **התועלת** העשירי הוא במצות והוא שהזהרנו מאכילת מעשר דגן ומעשר תירוש ומעשר יצהר חוץ ממקום הבחירה ומאכילת בשר חטאות ואשמות חוץ למחיצתן ומאכילת בכורים קודם הנחתן בעזרה ומאכילת בשר עולה או מה שהוא ראוי למזבח או בשר קדשם קדם זריקת דמים כי עדיין לא התורה אכילתן בשום מקום והנה התועלת בזאת האזהרה הוא שלא נבלבל הסדור שסדרה התורה באלו הענינים הנפלאים כדי שנתישר אל הכונה שכונה התורה בזה:
@1 **התועלת** האחת עשרה הוא במצות והוא מה שהוזהרנו שלא נעזוב הלוי והתועלת בזאת המצוה מבואר כדי שתהיה זאת המשפחה הנכבדת מיוחדת לעבודת יי' יתע' ולא יהיה לה טרדה ובאסיפ' מזונותיה ועוד כי המעשר ראשון מפני שאין לו קדושה אלי יקלו ישראל בנתינתו ללוים אבל יפרישוהו וישאירוהו להם ולא יהיה ללוים דבר יאכלו ממנו הפך מה שכונה התורה בהם ולזה הזהיר בזה המקום שלא לעזוב את הלוי:
@1 **התועלת** השתים עשרה הוא במצות והוא מה שצונו לשחוט בהמה חיה ועוף כשנרצה לאכלם כמו שאמר וזבחת מבקרך ומצאנך וגו' כאשר צויתיך לי מה שביארנו ביאור דבר זאת הפרשה והנה התועלת בזאת המצוה הוא מצדדין רבי' האח' כי בזה האופן יתכן יותר שיצא דם הבעלי חיים בעת שחיטתו ונהיה נשמרים יותר מפני זה מאכילת הדם. והשני כי בזה האון עם שכבר ימותו בו הבעלי חיים בקלות יותר הנה אין בו מה מהקנאה לנפשותינו תכונת האכזריות כדי שיהיה זה כשאר מיני ההמתה כאלו תאמר ההכאה בקופיץ על ראש הבעי חיים ומה שידמה לזה. והשלישי הוא יותר כולל הוא כי כאשר באה המצוה איך תעשה זאת ההמתה היקרה מזה לשוחט את הבעלי חיים שהוא לא יכוין להרוג את הבעלי חיים בעשותו זה הפעל אבל יהיה לבו איך יעשה זאת המצוה באון שצוה השם יתעלה וזה ממה שיהיה בו תועלת להמשך אליו הדבקות בשם יתעלה גם בעת עשותו זה להרחיק ממנו תכונת האכזריות לפי שהוא לא יכוין להרוג אך לעשות המצוה באופן שצוהו השם יתעלה:
@1 **התועלת** השלש עשרה הוא במצות והוא מה שצונו שלא לאכול אבר מן החי והנה התועלת בזאת האזהרה עם שבו ישמרו התועלות הנזכרו' בענין השחיטה הוא להרחיק ממנו תכונת הזוללות עד שלא יסבול ההמתנה שתשחט הבהמה אך מרוב הזוללות ימהר לקחת ממנו קודם שתשחט עם שבזה מהקנאת מדת האכזריות מה שלא יעלם:
@1 **התועלת** הארבע עשרה הוא במצות והוא מה שצונו להטפל בקרבנות אשר לנו עד הבאתם שם למקום הנבחר והתועלת בזאת המצוה מבואר כי לולי זה יפסדו הקדשים בראות מי שהפריש אותם שאינם באחריותו:
@1 **התועלת** החמש עשרה הוא במצות והוא מה שלמדנו בזה שאם פקעו מעל המערכ' מקרבן העולה הקרנים או הטלפים והעצמות והגידים אינו חייב להחזירם שם כי התורה לא דקדקה בעולה כי אם בבשר ובדם כאמרו ועשית עולותיך הבשר והדם:
@1 **התועלת** השש עשרה הוא במצות והוא מה שלמדנו שכל הזבחים שנתן מדמה מתנה אחת על המזבח הנה נרצה הבשר למזבח ולאדם ואין שאר המתנות מעכבות וזה למדנו מאמרו ודם זבחיך ישפך על מזבח יי' אלהיך והבשר תאכל כמו שביארנו בביאורנו לזה הפסוק והנה היה זה גם כן כשלא נוכל להשיג הטוב והתועלת בשלמות הנה אין ראוי שנקצר מהשתדלות אל שנשיג ממנו מה שאפשר לנו ולזה הוא מבואר שאף על פי שיש תועלת נפלא בהיות אלו המתנות אל התאר שהגבילה אותו התורה כמו שביארנו בפרשת ויקרא הנה יש בקרבנות תועלות אחרות נפלאות כמו שביארנו שם ולא הסכימה התורה שיעדרו ממנו אלו התועלות מפני העדר ממנו קצת התועלות אשר ימשכו מזריקת הדם על המזבח:
@1 **כי יכרית יי' אלהיך את הגוים וגו' עד עשר תעשר:**
@1 **ואולם התועלות המגיעים ממנה הם י"ח:**
@1 **התועלת** הראשון הוא להודיע שאין ראוי שנשתדל לעבוד השם יתעלה באופן שהיו עובדים עובדי עבודה זרה אלהיהם כי בנימוס העבודה זרה ההיא היה כל דבר שהוא מתועב ומרוחק מאד לאנשים מאד כי חשבו השחיתם עצמם עבודה עם שגם בניהם ובנותיהם היו שורפין באש לאלהיהם וזה הדרך דרכו בכל עניניהם ואולם תורתינו התמימה לא העמיסה עלינו דבר מגונה ובלתי נאות אך כל מה שסדרה לנו הוא חיי הגוף וחיי הנפש מתוק לנפש ומרפא לעצם:
@1 **התועלת** השני הוא במצות והוא מה שהזהירנו שלא נוסיף על הדבר שצוה אותנו ולא נגרע ממנו מאשר צוה אותנו כי זה ממה שיביא אל הפסד התורה בכללה רוצה לומ' אם היה זה השער פתוח לנו. ולזה סמך לזה דבר הנביא אשר יצוה לעבוד עבודה זרה והמסית והמדיח כאלו רצה בזה להישירנו שמזה המקום ימשך שיעבדו עבודה זרה:
@1 **התועלת** השלישי הוא להודיע שאין משגיחים באות וכמופת שיתן הנביא או חולם החלום שוה לעבוד עבודה זרה כי זה כל כך חזק האמות לנו שהוא עון פלילי ואין ראוי לעשות כן בשום פנים מצד מה שראינו בעינינו במעמד הר סיני ומצד העיון שאין כח באות ובמופת שיביאנו להאמין הפך זה:
@1 **התועלת** הרביעי הוא במצות והוא מה שהזהירנו מלשמוע אל דברי הנביא ההוא והתורה בזאת האזהרה מבואר כי בזה תתקיים האמונה האמתית והתורה השלמה:
@1 **התועלת** החמישי הוא במצות והוא מה שצוה להמית הנביא ההוא כדי לבער הרע מקרבנו רוצה לומר פן יפתנו בדבריו לסור מאחרי השם יתעלה:
@1 **התועלת** השישי הוא במצות והוא מה שהזהיר שלא יסית ולא ידיח איש מישר' לעבוד ע"ז מישראל איש או אנשים מישראל שנאמ' והנשארים ישמעו וייראו וגו' והנה התועלת בזאת המצוה מבואר:
@1 **התועלת** השביעי הוא במצות והוא מה שהזהיר שלא יפותה המוסת להסכים לדברי המסית שנאמ' ולא תאבה לו ולא תשמע אליו ומזה למדנו שאם אבה ושמע אף על פי שלא עבד עבודה זרה נסקל המוסת והנה התועלת בזאת האזהרה מבואר:
@1 **התועלת** השמיני הוא במצו' והוא מה שהזהירנו מלחוס על דם המסית ומלטעון עליו זכות ושלא נעמוד מלטעון עליו חובה אם ידענוהו לו שנאמר ולא תכסה עליו והתועלת באלו האזהרות מבואר כדי שיוסרו האנשים מעשות כדבר ההוא:
@1 **התועלת** התשיעי הוא במצו' והוא מה שצונו לסקול המסית שנאמר וסקלתו באבנים ומת והתועלת מבואר:
@1 **התועלת** העשירי הוא במצות והוא מה שצונו לחקור ולדרוש היטב עדות העדים וכ"ש בדיני נפשות כדי שנעמוד על בחינת מה שבעדות העדים מן האמת אל הפכו שנאמר ודרשת וחקרת ושאלת היטב וגומ'. והנה התועלת בזאת המצוה מבואר להגיע היושר והצדק במשפט:
@1 **התועלת** האחת עשרה הוא במצות והוא מה שצונו לדון במשפט עיר הנדחת לפי מה שצונו בתורה והנה היה התנאי שיהו מדיחיה מהעיר ומהשבט כי בזולת זה אפש' שבא הרע בזאת התכונ' לעיר ההיא במקרה אך כאר היה זה מבני העיר וממשפחתם מעיר על רוע תכונת אנשי המקו' ההוא ובפרט כשהודחו רוב אנשי העיר. ולפי שמרוע התכונה הזאת להם ימשך הרוע לזרעם בשכבר הוא להם קנין חזק היתה המצוה להרגם כלם טף ונשים ר"ל העובדים ע"ז מהם וצוה לשרוף העיר שלא תבנה עוד כי אולי מצד הסדורים אשר מהמערכת לכוכבים במקום ההוא ימשך ליושבי המקום ההוא זה הרצון עם שבזה תועלת ליסד הנשארים ולזאת הסבה צוה לשרוף כל שללה אל תוך רחובה ולהרוג כל בהמתה גם מהצדיקים בה כדי שישתדלו כל אחד שבעיר להוכיח החוטאים לפי כחו פן יאבדו קנייניו כלם לסבת חטאם:
@1 **התועלת** השתים עשרה הוא במצות והוא מה שהזהירנו שלא נהנה בדבר מקניני עיר הנדחת שנאמר לא ידבק בידך מאומה מן החרם והנה התועלת בזאת המצוה מבואר והוא שאם יהנה האדם בו ויצליחו קניניו אח' זה אולי יטעה ויאמר שהע"ז ההיא שהאמינו בה אנשי העיר ההיא הצליחו קנייניו ויהיה זה סבה אל שימשך לעבודה זרה:
@1 **התועלת** הי"ג הוא להודיע שהאכזריות על הרעים חמלה על הטובים כי העושה דין בעיר הנדחת משיב חרון אף ה' מעל ישראל ומביא עליהם רחמים:
@1 **התועלת** הארבע עשרה הוא במצו' והוא מה שהזהירנו שלא נסכול בעצמנו כדרך שהיו נוהגין לעשות עובדי עבודה זרה וזהו אמרו לא תתגודדו והנה התועלת בזאת המצוה הוא להרחיק מלכת בחקות עובדי ע"ז עם שזה שומר אותנו מלהשחית עצמנו ומביא אותנו להדבק בדברי התורה ולמאוס הנמוסים המגונים ההם שהיו לעובדי עבודה זרה:
@1 **התועלת** החמש עשרה הוא במצות והוא מה שהזהירנו מלשים קרחה על הראש למת כמו שהיו עושים הגוים ההם והו אמרו ולא תשימו קרחה בין עיניכם למת והתועלת בזאת המצוה היא כמו התועלת אשר במצוה שלפניה והנה המשיך לזה מה שצונו השם יתעלה לבחר בו מהמאכלים אשר הוא מבואר במעט עיון שהוא לטוב לנו כמו שביארנו בפרש' שמיני להעיר על עוצם ההבדל הנפלא שיש בין זאת התורה האלהית ובין הנמוסים המגונים שהיו לגוים ההם כי זאת התורה תשתדל ליסר לנו הנימוס המועיל לנו לגוף ולנפש בתכלית מה שאפשר ואולם הנמוסים ההם היו להשחית המתנהגים בהם הנפש וגם הבשר:
@1 **התועלת** השש עשרה הוא במצות והוא מה שהזהירתנו התורה מאכול הבהמה המתה שהיא בלתי שחוטה שנ' לא תאכלו כל נבלה והנה התועלת בזאת המצוה היא תחללה לפי שכבר יקרה על הרוב במתה שתהיה חולה ויהיה בשרה מזיק לאוכל והשני הוא לקיים מצות שחיטה אשר כבר זכרנו מה שבה מהתועלת:
@1 **התועלת** השבע עשרה הוא להודיע מה שחמלה התורה על הגר עד שכבר הקדימה נתינת הנבלה לגר על מכירתה לנכרי והתועלת בה שיהיה מזה לגר הוא לחמלה עליו כי אין לו עוזר ולזה ראוי שנחמול עליו אחר שהוא גר בינינו וקבל עליו שלא לעבוד עבודה זרה והתועלת במה שיהיה מזה לנכרי הוא ליסד בלבנו שאין ראוי שנחנהו לתת לו מתנות חנם לפי הוא עובד עבודה זרה:
@1 **התועלת** השמנה עשרה הוא במצות והוא מה שלמדנו בזה המקום מצד הסמיכות שהסבה באסור בשר בחלב הוא מצד היותו מזון בלתי נאות אל הבריאות כמו שביארנו בפרשת ואלה המשפטים:
@1 **עשר תעשר את כל תבואת זרעך עד סוף הפרשה.**
@1 **ואולם התועלות המגיעות מזאת הפרשה שהגבלנו ביאורה בזה המקום הם כ"ח:**
@1 **התועלת** הראשון הוא במצות והוא מה שצוה להפריש מעשר שני מכל התבואות והפרות אשר לנו לעלות לאכלו במקום הבחירה שנאמר עשר תעשר את כל תבואת זרעך והנה בזה תועלות רבות כמו שזכרנו אצל ביאורנו לזאת הפרשה ובכללם יגיע מהתועלת בה ללמדנו ליראה השם יתעלה כל הימים כמו שזכרה התורה וכבר ביארנו זאת אצל באורינו זאת הפרשה:
@1 **התועלת** השני הוא במצות והוא מה שצוה להפריש מעשר עני בשנה השלישית והששית מהשמטה רוצה לומר שהמעשר שני יהיה בשנים האלה לעניים והנה התועלת בזאת המצוה מבואר כי בזאת ימצא לעניים בקלות המצטרך להם ולא יכבד מאד לבעלים מה שיתנו להם מזה כי גם בשנים האחרו' לא היו משתמשים הבעלי' במעשר שני לתועלת גדול כי הם היו מצווים לאכלו במקום הבחירה בג' רגלים שיביאו שם עם שאר המעשרות שצו לאכול שם כמו מעש' בהמה ונדריהם ונדבותם כי זה יהיה סבה גם בשנים ההם שיתנו העשירים הרבה מזה המעשר:
@1 **התועלת** השלישי הוא במצות והוא מה שצונו להשמיט כספים בשנת השמיטה כי בזה תועלת להניח לעניים מהנושים בה עם ההערה שיש בכאן בענין השמיטה שנתחזק וזה מבואר ממה שזכרנו מהתועלת בדבר השמיטה בפרשת בהר סיני:
@1 **התועלת** הרביעי הוא במצות והוא מה שהזהירנו שלא לנגש המלוה שהוא אצל ישראל שעברה עליו שביעית שנאמר לא יגוש את רעהו:
@1 **התועלת** החמישי הוא במצות והוא מה שצונו לנגוש הנכרי כדי שלא נתן מתנות חנם לעובדי ע"ז והוא אמרו את הנכרית גוש:
@1 **התועלת** השישי הוא במצו והוא מה שצונו לעשות צדקה לעניים על מדרגותיהם רוצה לומר שהקרוב קרוב קודם והוא אמרו פתוח תפתח את ידך לאחיך לענייך ולאביונך בארצך:
@1 **התועלת** השביעי הוא במצות והוא מה שהזהירנו מלאמץ לבבנו ומלקפוץ ידינו מהעני מלהחיותו רוצה לומר מלהמציא לו די מחסורו שנאמר לא תאמץ את לבבך ולא תקפוץ את ידך מאחיך האביון וגו'. די מחסורו אשר יחסר לו:
@1 **התועלת** השמיני הוא במצות והוא מה שהזהירנו שלא נמנע מלהלוות לעני מפני קרבת שנת השמטה שנאמר השמר לך פן יהיה דבר עם לבבך בליעל לאמר קרבה שנת השבע שנת השמיטה וגומ' והתועלת בזאת הצדקה מבואר:
@1 **התועלת** התשיעי הוא במצות והוא מה שצוה להעניק לעבד עברי ולאמה העברית כפי אשר תשיג יד הבעלים שנאמר הענק תעניק לו מגרנך ומיקבך ואף לאמתך תעשה כן:
@1 **התועלת** העשירי הוא במדות והוא להודיע שאין ראוי לאדם שיעמוד בטל מפני שמרו מצות התורה ויסמך שהשם יתע' יתן לו צרכיו כי זה ממה שיביאהו אל החסרון ואולי יביא עם זה אל מעוט האמונה בשם יתעלה ולזה אמר וברכך ה' בכל אשר תעשה להעיר על שהוא צריך למתברך בשם יתעלה שלא ישב בטל אבל יעשה מעשים להביא אליו הברכה והשם יתעלה יביאה לו בכל אשר יעשה:
@1 **התועלת** האחת עשרה הוא במצות והוא מה שצוה להקדיש הבכור כשנולד ולומר שהוא בכור קדוש לש' והנה התועלת בזה הוא לפרסם מצות הבכורות שיש בהתועלת להזכיר עניין יציאת מצרים הנפלא שהוא מישיר מאד לעבודת השם יתעלה עם שבו תועלת לשמור האנשים מהכשל ליהנות בו:
@1 **התועלת** הי"ב והוא מה שהזהירתנו מלעבוד בבכור שור בין תם בין בעל מום ואף על פי שלא חסרנו דבר ממנו זולת העמל שהשיגו מזה שהוא מחוסר החום הטבעי ומלגוז בכור אף על פי שלא עמלנוהו ולא תסרנו ממנו דבר כי אם מה שהוא ממנו במדרגת המותר וכן הענין בשאר הקדשים כל שכן שהוא אסור ליהנות מהם במה שיחוסר בו דבר מגופם כמו הענין ביניקת חלב הקדשים והנה התועלת בזה הוא להעיר על שאלו הקדשים הם לה' ולזה לא הותר לנו ליהנות מהם:
@1 **התועלת** השלש עשרה הוא להודיע שהבכור תם לא נאכל כי אם במקום הבחירה. והנה הכונה בזה הוא להעיר שהוא לה' מפני מכת בכורות:
@1 **התועלת** הארבע עשרה הוא להודיע שהבכור נאכל שנה בשנה לא יגדלהו הכהן משנה לחברתה פן תקרה בזה תקלה שיהנה ממנו אם יגדל מהם הכהן עדרים:
@1 **התועלת** החמש עשרה הוא במצו' והו' להודיע שהבכור הבעל מום אינו נזבח ליי' בבית הבחיר' אבל אם היה בעל מום קבוע הוא נשחט במומו ונאכל בכל מקום בזולת קדושה שנאמר כי יהיה בו מם פסח או עור כל מום רע לא תזבחנו לה' אלהיך:
@1 **התועלת** השש עשרה הוא במצו' והוא מה שצונו להביא שלמי חגיגה עם הפסח במקום אשר יבחר יי' לפי שהפסח הוא כלו לבעלים מלבד דמו וחלבו שהוא למזבח רצה השם יתעלה שיתחברו עמו השלמים שאוכלים מהם השם יתעלה וכהניו וישראל על שלחן אחד:
@1 **התועלת** השבע עשרה הוא במצו' והוא מה שצונו שלא לזבח הפסח כי אם בבית הבחירה כי בזה תשלם יותר הכונה המכוונת בפסח לפי מה שביארנו מענינו בפרשת בא אל פרעה:
@1 **התועלת** השמנה עשרה הוא במצות והוא מה שצוונו שלא להותיר מבשר החגיגה עד הבקר כמו העניין בפסח שהיא באה עמו כדי שלא יחשוב חושב שתהיה קדושת הפסח למעלה מקדושת השלמים מפני שמעטה התורה בזמנו:
@1 **התועלת** התשע עשרה הוא במצות והוא מה שצונו לבשל ולאכל הפסח במקום אשר יבחר השם שנאמר ובשלת ואכלת במקום אשר יבחר ה' ולמדנו מזה שאם בשלו חוץ מהמקום ההוא הוא נפסל מלאכל וכבר למדנו זה בכללו' ממה שנאמר ובשר בשדה טרפה לא תאכלו כמו שביארנו בפרשת ואלה המשפטים:
@1 **התועלת** העשרים הוא במדות והוא מה שהודיענו כשנשוב מהמקום אשר יבחר ה' לא נסע כי אם בבקר אחר שנלין שם במקום הנבחר ההוא כאמרו ופנית בבקר והלכ' לאהלך וכבר זכרנו התועלות הנמשכים מזה אצל ביאורנו לזה הפסוק:
@1 **התועלת** העשרים ואחת הוא במצות והוא מה שלמדנו שהתחלת הקצירה ראוי שתהיה קצירת העומר ושהיא לא תהיה עד ליל י"ו בניסן כי מאז תתחיל הספירה וכבר ביארנו תועלת זאת המצוה במה שקדם:
@1 **התועלת** השנים ועשרים הוא במצות והוא מה שצונו לעשות שלמי חגיגה ושלמי שמחה בחג המצות ובחג השבועות ובחג הסכות והנה חוייב שתהיה החגיגה באה מן החולין כי היא העקר ועליה נקראו המועדים חגים והסכים שתהיה הנדבה ממנה באה ממעשר שני וממעשר בהמה ונדרים ונדבו' וכן הענין בשלמי שמחה כדי שלא תכבד ההוצאה לאנשים באם שם ויהיה זה סבה למעט שמחתם כי הרבה מה שיכאב לה האדם על רוב ההוצאה ובזה גם כן תשלם יותר כונת התורה שישמחו הבעלים עם האנשים הדלים כמו הגר והלוי והיתום והאלמנה ויתר העניים ולא יקשה בעיני הבעלים בתתם להם מזה אחר שאין להם דרך לאכלו חוץ ממקום הבחירה:
@1 **התועלת** השלש ועשרים הוא במצות והוא מה שצותה התורה להראות כל הזכרים את פני השם יתעלה בג' המועדים שהם פסח שבועות סכות והתועלת בזה מבואר במה שביארנו מזה בזאת הפרשה:
@1 **התועלת** הארבע ועשרי' הוא במצות והוא מה שהזהרנו לבלתי הראו' לפניו רקם כי זה ממה שיישיר האנשים כי הענינים שהם מסודרים בבית הגדול אינם ללא תועלת כי גם ראייתם לא הסכימה התורה שתהיה רקם עם שהעולה שיקריבו שם על הראיה היא מישרת בעצמותה לדברים. נפלאים כמו שבארנו אצל ביאורנו הקרבנות:
@1 **התועלת** החמש ועשרים הוא במדו' והוא להודיע שראוי לכל אדם שיצמצם לפי אשר תשיג ידו כדי שיוכל להתמיד בהוצאה זו כי בזולת וזה אולי ישחית קנינו בעת אחת וישאר אחרי כן בחוסר כל ולזה אמרה התורה מסת נדבת ידך אשר תתן כאשר יברכך יי' אלהיך ואמר איש כמתנת ידו כברכת יי' אלהיך אשר נתן לך:
